AChB,YAAaA,KAAE,gDACf,YAAW,QACX,iBAAgB,QAChB,YAAW,mHAKT,QAAO,MAWP,CATD,SAAmB,QAAc,SAAM,GAD/C,MAUS,SARP,QAAQ,WACR,KAAK,KACL,MAAM,oBACL,SAAQ,CAAG,QACX,QAAS,QACT,QAAO,oBAER,cAA4C,CAAzCA,SAAE,62BCyBb,IAAM,EAAO,EAQP,CAAE,SAAQ,IAAG,MAAO,EAAQ,EAC5B,CAAE,QAAS,gBAAgB,EAC3B,CAAE,gBAAiB,GAAkB,EAE3C,SAAS,eAAe,EAAsB,CAC5C,IAAM,EAAU,sBAAsB,EAAK,YAAY,EAAE,OAEzD,OADI,EAAG,CAAO,EAAU,EAAE,CAAO,EAC1B,EACJ,YAAY,EACZ,MAAM,OAAO,EACb,OAAO,OAAO,EACd,IAAK,GAAS,EAAK,OAAO,CAAC,CAAC,CAAC,YAAY,EAAI,EAAK,MAAM,CAAC,CAAC,EAC1D,KAAK,GAAG,CACb,CAIA,SAAS,mBAAmB,EAAsB,CAChD,IAAM,EAAU,EAAU,CAA8B,EACxD,OAAO,EAAW,GAAe,CAAO,GAAK,EAAK,CACpD,CAEA,IAAM,EAAO,MACX,WACI,CACE,KAAM,EAAE,4BAA4B,EACpC,eAAgB,WAAS,OAC3B,EACA,CACE,KAAM,eAAe,cAAY,SAAS,IAAI,EAC9C,eAAgB,mBAAmB,cAAY,SAAS,IAAI,CAC9D,CACN,EAEM,EAAkB,MAAe,CACrC,IAAM,EAAO,cAAY,cAAc,KAEvC,OADK,EACE,EAAK,YAAY,IAAM,OAC1B,EAAE,4BAA4B,EAC9B,eAAe,CAAI,EAHL,EAIpB,CAAC,gBAxIC,MA0BE,OAzBC,6BACA,aACA,oBAAmB,QACnB,UACA,YACA,sBAAqB,OAAY,KACjC,yBAAwB,IAAY,EAAE,aAAW,GACjD,wBAAuB,IAAY,EAAE,QACrC,yBACA,yBACA,yCACA,6CACA,6CACA,0DACA,oCACA,uDACA,sDACA,yCACA,uCACA,4CACA,gBAAc,UAAE,EAAI,iBACpB,UAAO,UAAE,EAAI,UAAY,CAAM,EAC/B,OAAI,UAAE,EAAI,QACV,qBAAoB,UAAE,EAAI,qBAAuB,CAAM,EACvD,kBAAgB,UAAE,EAAI","names":["$emit","$t"],"ignoreList":[],"sources":["../../packages/account-ui/src/billing/stripe/StripePaymentForm.vue","../../packages/account-ui/src/billing/checkout/CheckoutButton.vue","../../packages/account-ui/src/billing/checkout/CheckoutPaymentForm.vue","../../packages/account-ui/src/billing/checkout/CheckoutSavedMethodSelect.vue","../../packages/account-ui/src/billing/checkout/CheckoutSavedMethods.vue","../../packages/account-ui/src/billing/checkout/CheckoutPromotionCode.vue","../../packages/account-ui/src/billing/checkout/CheckoutPaymentNotices.vue","../../packages/account-ui/src/billing/checkout/checkoutCopy.ts","../../packages/account-ui/src/billing/checkout/CheckoutTermsNote.vue","../../packages/account-ui/src/billing/checkout/CheckoutVerificationPrompt.vue","../../packages/account-ui/src/billing/checkout/CheckoutSubscribeActions.vue","../../packages/account-ui/src/billing/checkout/CheckoutSubscribeSummary.vue","../../packages/account-ui/src/billing/checkout/checkoutRecovery.ts","../../packages/account-ui/src/billing/checkout/CheckoutSubscribeConfirm.vue","../../packages/account-ui/src/billing/checkout/CheckoutSuccess.vue","../../packages/account-ui/src/billing/checkout/CheckoutReactivationBanner.vue","../../packages/account-ui/src/billing/checkout/CheckoutTransitionSummary.vue","../../packages/account-ui/src/billing/checkout/CheckoutTransitionTotal.vue","../../packages/account-ui/src/billing/checkout/CheckoutTransitionConfirm.vue","../../src/platform/cloud/subscription/constants/teamPlanCreditStops.ts","../../src/platform/workspace/utils/workspaceCheckoutTelemetry.ts","../../src/platform/workspace/composables/useSubscriptionCheckout.ts","../../src/platform/workspace/composables/useCheckoutCopy.ts","../../src/platform/workspace/components/SubscriptionAddPaymentPreviewWorkspace.vue","../../src/platform/workspace/components/SubscriptionSuccessWorkspace.vue","../../src/platform/workspace/components/SubscriptionTransitionPreviewWorkspace.vue"],"sourcesContent":["<template>\n  <form class=\"flex min-h-0 flex-col gap-6 xl:flex-1\" @submit.prevent=\"submit\">\n    <div v-if=\"!pageLayout\" class=\"flex items-start justify-between gap-4\">\n      <div>\n        <h3\n          :id=\"headingId\"\n          class=\"m-0 text-base font-semibold text-base-foreground\"\n        >\n          {{ copy.paymentMethod }}\n        </h3>\n        <p class=\"m-0 mt-1 max-w-md text-sm text-muted-foreground\">\n          {{ copy.methodChoice }}\n        </p>\n      </div>\n    </div>\n    <div\n      v-if=\"configurationError\"\n      class=\"rounded-lg border border-destructive-background bg-destructive-background/10 px-3 py-2 text-sm text-destructive-background\"\n    >\n      {{ configurationError }}\n    </div>\n    <!-- Only the form region scrolls; the header above and the pay action\n         below hold their positions regardless of which method is expanded. -->\n    <div\n      role=\"group\"\n      :aria-labelledby=\"pageLayout ? undefined : headingId\"\n      :aria-label=\"pageLayout ? copy.paymentMethod : undefined\"\n      :inert=\"locked\"\n      class=\"flex flex-col gap-6 xl:min-h-0 xl:flex-1 xl:overflow-x-hidden xl:overflow-y-auto xl:pr-1\"\n    >\n      <div ref=\"paymentElementTarget\" />\n      <div class=\"flex flex-col gap-3\">\n        <h4\n          :class=\"\n            cn(\n              'm-0 text-base-foreground',\n              pageLayout ? 'text-base font-normal' : 'text-sm font-medium'\n            )\n          \"\n        >\n          {{ copy.billingAddress }}\n        </h4>\n        <div ref=\"addressElementTarget\" />\n      </div>\n      <div\n        v-if=\"selectedMethodType === 'alipay'\"\n        class=\"flex items-start gap-3 rounded-xl bg-base-background/60 px-4 py-3 text-xs text-muted-foreground\"\n      >\n        <i\n          class=\"mt-0.5 icon-[lucide--shield-check] size-4 shrink-0 text-(--success-foreground)\"\n        />\n        <p class=\"m-0\">\n          {{ copy.alipayRenewalNote }}\n        </p>\n      </div>\n    </div>\n    <slot\n      name=\"submit\"\n      :disabled=\"submitDisabled\"\n      :loading=\"isLoading || isSubmitting\"\n      :verification-pending=\"verificationPending\"\n    />\n  </form>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The provider-bound half of checkout: mounts Stripe's Payment and Address\n * Elements, validates them, and turns them into a confirmation token the\n * caller hands to `subscribe`. Everything host-shaped arrives as an input —\n * the publishable key, the copy, the pay button through the `submit` slot —\n * and every observation leaves as a `phase` event, so the package chooses no\n * design system, no i18n runtime and no telemetry sink.\n */\nimport type {\n  Appearance,\n  Stripe,\n  StripeAddressElement,\n  StripeElements,\n  StripeError,\n  StripePaymentElement\n} from '@stripe/stripe-js'\nimport { loadStripe } from '@stripe/stripe-js/pure'\nimport { computed, onBeforeUnmount, onMounted, ref, useId, watch } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport type {\n  StripePaymentCopy,\n  StripePaymentPhase,\n  StripeSubmitPhase\n} from './stripePaymentPhase'\n\nconst {\n  publishableKey,\n  amountCents,\n  currency,\n  copy,\n  paymentMethodConfigurationId = '',\n  isLoading = false,\n  verificationPending = false,\n  canSubmit = true,\n  locked = false,\n  themeKey = '',\n  pageLayout = false\n} = defineProps<{\n  publishableKey: string\n  amountCents: number\n  currency: string\n  copy: StripePaymentCopy\n  /** Stripe payment method configuration governing which methods Elements\n   *  offers (served per-environment by the preview). */\n  paymentMethodConfigurationId?: string\n  isLoading?: boolean\n  /** A 3DS verification is pending: the host's own verification action is\n   *  primary, so the pay button steps back. */\n  verificationPending?: boolean\n  canSubmit?: boolean\n  /** Money is on its way: the elements are inert until the attempt resolves. */\n  locked?: boolean\n  /** Changes whenever the host switches theme, so the mounted Elements\n   *  re-read their appearance in place instead of keeping the colours\n   *  resolved at creation. */\n  themeKey?: string\n  /** The full-page checkout titles the column itself, so the form drops its\n   *  heading and subtitle and sets the address label in the body style. */\n  pageLayout?: boolean\n}>()\n\nconst emit = defineEmits<{\n  /** `paymentMethodType` is the token's method (`card`, `alipay`, …), so the host knows a redirect is coming. */\n  confirm: [confirmationToken: string, paymentMethodType: string]\n  submittingChange: [submitting: boolean]\n  phase: [phase: StripePaymentPhase]\n}>()\n\nconst headingId = useId()\n\nlet isUnmounted = false\n\nfunction reportPhase(phase: StripePaymentPhase): void {\n  // A callback or awaited continuation can fire after unmount; the host's\n  // journey may then belong to a later checkout, so never report for it.\n  if (isUnmounted) return\n  emit('phase', phase)\n}\n\nconst paymentElementTarget = ref<HTMLDivElement>()\nconst addressElementTarget = ref<HTMLDivElement>()\nconst stripeElements = ref<StripeElements>()\nconst configurationError = ref('')\nconst isSubmitting = ref(false)\nconst selectedMethodType = ref('')\nlet stripe: Stripe | null = null\nlet paymentElement: StripePaymentElement | undefined\nlet addressElement: StripeAddressElement | undefined\n\nconst submitDisabled = computed(\n  () => !stripeElements.value || !canSubmit || verificationPending\n)\n\nconst submitBlocked = computed(\n  () => submitDisabled.value || isSubmitting.value || isLoading\n)\n\nfunction failElementInit(): void {\n  configurationError.value = copy.unavailable\n  reportPhase({\n    phase: 'payment_element_failed',\n    element: 'payment',\n    element_phase: 'init'\n  })\n}\n\nfunction failSubmit(submitPhase: StripeSubmitPhase, error?: StripeError): void {\n  configurationError.value = error?.message ?? copy.genericError\n  reportPhase({\n    phase: 'payment_submit_failed',\n    submit_phase: submitPhase,\n    ...(error?.code && { error_code: error.code })\n  })\n}\n\nfunction mountPaymentElement(\n  elements: StripeElements,\n  target: HTMLDivElement\n): void {\n  paymentElement = elements.create('payment', {\n    layout: {\n      type: 'accordion',\n      defaultCollapsed: false,\n      radios: 'always',\n      spacedAccordionItems: true\n    },\n    // The Address Element below is the single source of billing address.\n    // Left at the default, card would also render its own country/postal\n    // inputs, and a customer who filled the two differently would send the\n    // issuer an address that contradicts the one we collected for AVS.\n    fields: { billingDetails: { address: 'never' } },\n    // The host's terms note carries the recurring-charge authorization;\n    // Stripe's card mandate text would say it twice.\n    terms: { card: 'never' }\n  })\n  paymentElement.mount(target)\n  paymentElement.on('ready', () => {\n    reportPhase({ phase: 'payment_element_ready', element: 'payment' })\n  })\n  paymentElement.on('loaderror', (event) => {\n    reportPhase({\n      phase: 'payment_element_failed',\n      element: 'payment',\n      element_phase: 'mount',\n      ...(event.error?.code && { error_code: event.error.code })\n    })\n  })\n  // Method-specific notes (e.g. the Alipay auto-renewal disclosure) key off\n  // whichever payment method the user has selected inside the element.\n  paymentElement.on('change', (event) => {\n    selectedMethodType.value = event.value?.type ?? ''\n  })\n}\n\n/**\n * A full billing address feeds AVS to the issuer and Radar. In billing mode\n * every field is required, and because the address shares the Payment\n * Element's group, createConfirmationToken folds it into the token's\n * billing_details.\n */\nfunction mountAddressElement(\n  elements: StripeElements,\n  target: HTMLDivElement\n): void {\n  addressElement = elements.create('address', { mode: 'billing' })\n  addressElement.mount(target)\n  addressElement.on('ready', () => {\n    reportPhase({ phase: 'payment_element_ready', element: 'address' })\n  })\n  addressElement.on('loaderror', (event) => {\n    reportPhase({\n      phase: 'payment_element_failed',\n      element: 'address',\n      element_phase: 'mount',\n      ...(event.error?.code && { error_code: event.error.code })\n    })\n  })\n}\n\nonMounted(async () => {\n  if (!publishableKey || !paymentMethodConfigurationId) {\n    failElementInit()\n    return\n  }\n  // A non-positive amount means the caller mounted this before its quote\n  // resolved. Stay silent rather than latching an error the caller cannot\n  // clear: callers gate on a ready quote, and a wrong error here reads to the\n  // customer as \"payment is broken\" when the amount is merely still loading.\n  if (amountCents <= 0) return\n\n  try {\n    stripe = await loadStripe(publishableKey)\n  } catch {\n    failElementInit()\n    return\n  }\n  if (!stripe || !paymentElementTarget.value || isUnmounted) {\n    failElementInit()\n    return\n  }\n  stripeElements.value = stripe.elements({\n    mode: 'subscription',\n    amount: amountCents,\n    currency: currency.toLowerCase(),\n    // Intent-wide by policy: every method offered here must be chargeable\n    // off-session at renewal, so Stripe's dynamic filtering is the gate —\n    // a configuration-enabled method without off-session support (or without\n    // this account's permission for it) simply never renders.\n    setupFutureUsage: 'off_session',\n    paymentMethodConfiguration: paymentMethodConfigurationId,\n    appearance: resolveAppearance(paymentElementTarget.value)\n  })\n  mountPaymentElement(stripeElements.value, paymentElementTarget.value)\n  if (addressElementTarget.value) {\n    mountAddressElement(stripeElements.value, addressElementTarget.value)\n  }\n})\n\nwatch([() => amountCents, () => currency], ([amount, nextCurrency]) => {\n  if (!stripeElements.value || amount <= 0) return\n\n  stripeElements.value\n    .update({ amount, currency: nextCurrency.toLowerCase() })\n    .catch(() => {\n      if (isUnmounted) return\n      configurationError.value = copy.genericError\n      reportPhase({\n        phase: 'payment_element_failed',\n        element: 'payment',\n        element_phase: 'update'\n      })\n    })\n})\n\nwatch(\n  () => themeKey,\n  () => {\n    if (!stripeElements.value || !paymentElementTarget.value) return\n    stripeElements.value\n      .update({ appearance: resolveAppearance(paymentElementTarget.value) })\n      .catch(() => {\n        reportPhase({\n          phase: 'payment_element_failed',\n          element: 'payment',\n          element_phase: 'update'\n        })\n      })\n  },\n  { flush: 'post' }\n)\n\nonBeforeUnmount(() => {\n  isUnmounted = true\n  paymentElement?.destroy()\n  addressElement?.destroy()\n})\n\ninterface MintedToken {\n  readonly id: string\n  readonly paymentMethodType: string\n}\n\nasync function mintConfirmationToken(\n  elements: StripeElements,\n  client: Stripe\n): Promise<MintedToken | undefined> {\n  // Validation boundary: submit() normally resolves with an error field, but\n  // an unexpected rejection here is still a pre-token validation failure.\n  let submitResult\n  try {\n    submitResult = await elements.submit()\n  } catch {\n    failSubmit('validation')\n    return undefined\n  }\n  if (submitResult.error) {\n    failSubmit('validation', submitResult.error)\n    return undefined\n  }\n  const result = await client.createConfirmationToken({ elements })\n  if (result.error) {\n    failSubmit('token_creation', result.error)\n    return undefined\n  }\n  return {\n    id: result.confirmationToken.id,\n    paymentMethodType: result.confirmationToken.payment_method_preview.type\n  }\n}\n\nasync function submit() {\n  if (submitBlocked.value || !stripeElements.value || !stripe) return\n  isSubmitting.value = true\n  emit('submittingChange', true)\n  configurationError.value = ''\n  reportPhase({ phase: 'payment_submit_attempted' })\n  try {\n    const confirmationToken = await mintConfirmationToken(\n      stripeElements.value,\n      stripe\n    )\n    // Same hazard as reportPhase, with money on it: the customer may have\n    // closed this checkout while the token was minting, and a confirm the\n    // host acts on would charge them for a flow they left.\n    if (confirmationToken && !isUnmounted)\n      emit('confirm', confirmationToken.id, confirmationToken.paymentMethodType)\n  } catch {\n    failSubmit('token_creation')\n  } finally {\n    isSubmitting.value = false\n    if (!isUnmounted) emit('submittingChange', false)\n  }\n}\n\n/**\n * Stripe takes appearance as concrete values, so every token is resolved\n * against the form's own theme root, where the host's theme class applies.\n */\nfunction resolveAppearance(themeRoot: HTMLElement): Appearance {\n  const resolveThemeColor = (variable: string) =>\n    resolveColorIn(themeRoot, variable)\n  return {\n    variables: {\n      // Selection (radio, selected label, accordion highlight) uses the\n      // theme-aware foreground rather than brand blue.\n      colorPrimary: resolveThemeColor('--base-foreground'),\n      colorBackground: resolveThemeColor('--base-background'),\n      colorText: resolveThemeColor('--base-foreground'),\n      colorTextSecondary: resolveThemeColor('--muted-foreground'),\n      colorDanger: resolveThemeColor('--destructive-background'),\n      // Same token as the pricing table's \"Save 20%\" pill, so all\n      // deal/discount badges share one accent.\n      colorSuccess: resolveThemeColor('--primary-background'),\n      fontFamily: getComputedStyle(themeRoot).fontFamily,\n      borderRadius: '10px',\n      spacingUnit: '5px'\n    },\n    rules: {\n      '.AccordionItem': {\n        backgroundColor: resolveThemeColor('--base-background'),\n        // Transparent (not none) so rows keep their size when the\n        // selected item paints its outline.\n        border: '1px solid transparent',\n        boxShadow: 'none'\n      },\n      '.AccordionItem--selected': {\n        borderColor: resolveThemeColor('--base-foreground')\n      },\n      '.Input': {\n        backgroundColor: resolveThemeColor('--input-surface'),\n        borderColor: resolveThemeColor('--border-default'),\n        boxShadow: 'none'\n      },\n      '.Input:focus': {\n        borderColor: resolveThemeColor('--primary-background'),\n        boxShadow: `0 0 0 1px ${resolveThemeColor('--primary-background')}`\n      },\n      '.Label': {\n        fontWeight: '500'\n      }\n    }\n  }\n}\n\nfunction resolveColorIn(themeRoot: HTMLElement, variable: string) {\n  const probe = document.createElement('span')\n  probe.style.color = `var(${variable})`\n  themeRoot.append(probe)\n  const color = getComputedStyle(probe).color\n  probe.remove()\n  return color\n}\n</script>\n","<template>\n  <button\n    :type\n    :disabled=\"disabled || loading\"\n    :aria-busy=\"loading || undefined\"\n    :class=\"cn(buttonVariants({ variant, size }), customClass)\"\n  >\n    <i v-if=\"loading\" class=\"pi pi-spin pi-spinner\" aria-hidden=\"true\" />\n    <template v-if=\"loading\">\n      <span class=\"sr-only\"><slot /></span>\n    </template>\n    <slot v-else />\n  </button>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The cloud app's Button, as a native button: same variant classes, same\n * loading treatment (spinner with the label kept for screen readers).\n */\nimport type { HTMLAttributes } from 'vue'\n\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport { buttonVariants } from '@comfyorg/design-system/button.variants'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  type = 'button',\n  class: customClass = '',\n  loading = false,\n  disabled = false\n} = defineProps<{\n  type?: 'button' | 'submit'\n  variant?: ButtonVariants['variant']\n  size?: ButtonVariants['size']\n  class?: HTMLAttributes['class']\n  loading?: boolean\n  disabled?: boolean\n}>()\n</script>\n","<template>\n  <StripePaymentForm\n    :publishable-key\n    :amount-cents\n    :currency\n    :copy\n    :payment-method-configuration-id\n    :is-loading\n    :verification-pending\n    :can-submit\n    :theme-key\n    @confirm=\"(token, methodType) => emit('confirm', token, methodType)\"\n    @submitting-change=\"emit('submittingChange', $event)\"\n    @phase=\"emit('phase', $event)\"\n  >\n    <template #submit=\"{ disabled, loading, verificationPending: pending }\">\n      <CheckoutButton\n        type=\"submit\"\n        :variant=\"pending ? 'tertiary' : 'inverted'\"\n        size=\"lg\"\n        class=\"w-full rounded-lg\"\n        :disabled\n        :loading\n      >\n        {{ submitLabel }}\n      </CheckoutButton>\n    </template>\n  </StripePaymentForm>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The payment form with the checkout's pay button: the card entry both the\n * cloud app and billing-web show when no saved method stands in for it.\n */\nimport StripePaymentForm from '../stripe/StripePaymentForm.vue'\nimport type {\n  StripePaymentCopy,\n  StripePaymentPhase\n} from '../stripe/stripePaymentPhase'\nimport CheckoutButton from './CheckoutButton.vue'\n\nconst {\n  publishableKey,\n  amountCents,\n  currency,\n  copy,\n  submitLabel,\n  paymentMethodConfigurationId = '',\n  isLoading = false,\n  verificationPending = false,\n  canSubmit = true,\n  themeKey\n} = defineProps<{\n  publishableKey: string\n  amountCents: number\n  currency: string\n  copy: StripePaymentCopy\n  submitLabel: string\n  /** Governs which methods Elements offers (served per environment). */\n  paymentMethodConfigurationId?: string\n  isLoading?: boolean\n  /** A 3DS verification is pending: the pay button steps back. */\n  verificationPending?: boolean\n  canSubmit?: boolean\n  themeKey?: string\n}>()\n\nconst emit = defineEmits<{\n  confirm: [confirmationToken: string, paymentMethodType: string]\n  submittingChange: [submitting: boolean]\n  phase: [phase: StripePaymentPhase]\n}>()\n</script>\n","<template>\n  <SelectRoot v-model=\"selected\" v-model:open=\"isOpen\">\n    <SelectTrigger\n      :aria-label=\"label\"\n      :class=\"selectTriggerVariants({ size: 'lg', border: 'none' })\"\n    >\n      <div\n        class=\"flex flex-1 items-center gap-2 overflow-hidden py-2 pl-2 text-sm\"\n      >\n        <SelectValue class=\"truncate\" />\n      </div>\n      <div :class=\"selectDropdownClass\">\n        <i class=\"icon-[lucide--chevron-down] text-muted-foreground\" />\n      </div>\n    </SelectTrigger>\n\n    <SelectPortal>\n      <SelectContent\n        position=\"popper\"\n        :side-offset=\"8\"\n        align=\"start\"\n        :class=\"cn(selectContentClass, 'min-w-(--reka-select-trigger-width)')\"\n        @keydown=\"onContentKeydown\"\n      >\n        <SelectViewport\n          :style=\"{ maxHeight: 'min(28rem, 50vh)' }\"\n          class=\"scrollbar-custom w-full\"\n        >\n          <SelectItem\n            v-for=\"option in options\"\n            :key=\"option.value\"\n            :value=\"option.value\"\n            :class=\"selectItemVariants({ layout: 'single' })\"\n          >\n            <SelectItemText class=\"truncate\">\n              {{ option.name }}\n            </SelectItemText>\n            <SelectItemIndicator\n              class=\"flex shrink-0 items-center justify-center\"\n            >\n              <i\n                class=\"icon-[lucide--check] text-base-foreground\"\n                aria-hidden=\"true\"\n              />\n            </SelectItemIndicator>\n          </SelectItem>\n        </SelectViewport>\n      </SelectContent>\n    </SelectPortal>\n  </SelectRoot>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The cloud app's single select, reduced to what the saved-method picker\n * uses: the large trigger and a flat option list.\n */\nimport {\n  SelectContent,\n  SelectItem,\n  SelectItemIndicator,\n  SelectItemText,\n  SelectPortal,\n  SelectRoot,\n  SelectTrigger,\n  SelectValue,\n  SelectViewport\n} from 'reka-ui'\nimport { ref } from 'vue'\n\nimport {\n  selectContentClass,\n  selectDropdownClass,\n  selectItemVariants,\n  selectTriggerVariants,\n  stopEscapeToDocument\n} from '@comfyorg/design-system/select.variants'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { label, options } = defineProps<{\n  label: string\n  options: readonly { name: string; value: string }[]\n}>()\n\nconst selected = defineModel<string>({ required: true })\n\nconst isOpen = ref(false)\n\nfunction onContentKeydown(event: KeyboardEvent) {\n  if (event.key === 'Escape') {\n    stopEscapeToDocument(event)\n    isOpen.value = false\n  }\n}\n</script>\n","<template>\n  <div class=\"flex flex-col gap-2 pt-6\">\n    <span class=\"text-sm text-muted-foreground\">\n      {{ copy.savedPaymentMethod }}\n    </span>\n    <div\n      v-if=\"methods.length === 1\"\n      class=\"flex h-10 items-center gap-3 rounded-lg bg-secondary-background px-4\"\n    >\n      <i\n        :class=\"\n          cn(\n            'size-4 shrink-0',\n            methods[0].type === 'alipay'\n              ? 'icon-[lucide--wallet]'\n              : 'icon-[lucide--credit-card]'\n          )\n        \"\n      />\n      <span class=\"text-sm text-base-foreground tabular-nums\">\n        {{ methodLabel(methods[0]) }}\n      </span>\n      <CheckoutButton\n        variant=\"link\"\n        size=\"lg\"\n        class=\"ml-auto px-0\"\n        @click=\"emit('changePaymentMethod')\"\n      >\n        {{ copy.changePaymentMethod }}\n      </CheckoutButton>\n    </div>\n    <CheckoutSavedMethodSelect\n      v-else\n      v-model=\"selectedMethod\"\n      :label=\"copy.selectLabel\"\n      :options=\"options\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The saved payment methods standing in for the card form. One method shows\n * a Change affordance; two or more become a picker whose last option adds a\n * new method. Cards carry brand + last4; Alipay is a linked account with\n * neither.\n */\nimport { computed } from 'vue'\n\nimport type { SavedPaymentMethod } from '@comfyorg/account-core/billing'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport CheckoutButton from './CheckoutButton.vue'\nimport CheckoutSavedMethodSelect from './CheckoutSavedMethodSelect.vue'\nimport type { CheckoutSavedMethodCopy } from './checkoutCopy'\n\nconst ADD_NEW = 'add-new'\n\nconst { methods, copy } = defineProps<{\n  methods: readonly SavedPaymentMethod[]\n  copy: CheckoutSavedMethodCopy\n}>()\n\nconst emit = defineEmits<{\n  changePaymentMethod: []\n}>()\n\nconst selectedMethodId = defineModel<string | null>('selectedMethodId', {\n  default: null\n})\n\nfunction methodLabel(method: SavedPaymentMethod): string {\n  if (method.type === 'alipay') return copy.alipay\n  return `${method.brand} •••• ${method.last4}`\n}\n\nconst options = computed(() => [\n  ...methods.map((method) => ({\n    name: methodLabel(method),\n    value: method.id\n  })),\n  { name: copy.addNewPaymentMethod, value: ADD_NEW }\n])\n\nconst selectedMethod = computed({\n  get: () => selectedMethodId.value ?? '',\n  set: (value: string) => {\n    if (value === ADD_NEW) {\n      selectedMethodId.value = null\n      emit('changePaymentMethod')\n      return\n    }\n    selectedMethodId.value = value\n  }\n})\n</script>\n","<template>\n  <div class=\"flex gap-2 pt-6\">\n    <input\n      v-model=\"code\"\n      :aria-label=\"copy.promoCodePlaceholder\"\n      :disabled\n      class=\"h-10 min-w-0 flex-1 rounded-lg border border-interface-stroke bg-secondary-background px-3 text-base-foreground\"\n      :placeholder=\"copy.promoCodePlaceholder\"\n      @input=\"invalidateEditedCode\"\n    />\n    <CheckoutButton\n      variant=\"secondary\"\n      size=\"lg\"\n      :disabled\n      @click=\"emit('apply', code)\"\n    >\n      {{ copy.applyPromoCode }}\n    </CheckoutButton>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue'\n\nimport CheckoutButton from './CheckoutButton.vue'\nimport type { CheckoutCopy } from './checkoutCopy'\n\nconst {\n  appliedCode,\n  disabled = false,\n  copy\n} = defineProps<{\n  /** The code the current quote was priced with. */\n  appliedCode: string | undefined\n  disabled?: boolean\n  copy: Pick<CheckoutCopy, 'promoCodePlaceholder' | 'applyPromoCode'>\n}>()\n\nconst emit = defineEmits<{\n  apply: [code: string]\n  /** The typed code no longer matches the quote, so the quote is stale. */\n  invalidate: []\n}>()\n\nconst code = ref(appliedCode ?? '')\nwatch(\n  () => appliedCode,\n  (applied) => {\n    code.value = applied ?? ''\n  }\n)\n\nfunction invalidateEditedCode() {\n  if (code.value !== (appliedCode ?? '')) emit('invalidate')\n}\n</script>\n","<template>\n  <div\n    v-if=\"embeddedCheckoutEnabled && reconciliationOperationId\"\n    class=\"rounded-lg border border-interface-stroke bg-secondary-background p-4\"\n  >\n    <p class=\"m-0 font-semibold text-base-foreground\">\n      {{ copy.reconciliationTitle }}\n    </p>\n    <p class=\"m-0 mt-1 text-sm text-muted-foreground\">\n      {{ copy.reconciliationDetail }}\n      <span class=\"font-mono\">{{ reconciliationOperationId }}</span>\n    </p>\n  </div>\n\n  <div\n    v-if=\"embeddedCheckoutEnabled && authenticationState === 'failed_retryable'\"\n    role=\"alert\"\n    class=\"rounded-lg border border-interface-stroke bg-secondary-background p-4 text-sm text-base-foreground\"\n  >\n    {{ authenticationError || copy.authenticationFailedDetail }}\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/** What an earlier payment attempt left for the customer to read. */\nimport type { BillingAuthenticationState } from '@comfyorg/account-core/billing'\n\nimport type { CheckoutCopy } from './checkoutCopy'\n\nconst {\n  embeddedCheckoutEnabled,\n  reconciliationOperationId,\n  authenticationState,\n  authenticationError,\n  copy\n} = defineProps<{\n  embeddedCheckoutEnabled: boolean\n  reconciliationOperationId: string | null\n  authenticationState: BillingAuthenticationState | null\n  authenticationError: string | null\n  copy: Pick<\n    CheckoutCopy,\n    | 'reconciliationTitle'\n    | 'reconciliationDetail'\n    | 'authenticationFailedDetail'\n  >\n}>()\n</script>\n","import type { SubscriptionPreview } from '@comfyorg/account-core/billing'\n\nimport type { StripePaymentCopy } from '../stripe/stripePaymentPhase'\n\n/**\n * Host-translated strings for the checkout surfaces. Interpolated strings\n * are functions of typed params, so the package carries no i18n runtime and\n * a host cannot leave a placeholder unfilled. Sentences that wrap an element\n * around a placeholder keep the `{name}` token and are split at render time.\n */\nexport interface CheckoutTermsCopy {\n  /** Carries `{terms}` and `{privacy}` for the two links. */\n  readonly agreement: string\n  readonly terms: string\n  readonly privacyPolicy: string\n}\n\nexport interface CheckoutSavedMethodCopy {\n  readonly savedPaymentMethod: string\n  readonly changePaymentMethod: string\n  readonly addNewPaymentMethod: string\n  readonly alipay: string\n  readonly selectLabel: string\n}\n\ntype DiscountKind = NonNullable<\n  SubscriptionPreview['discounts']\n>[number]['kind']\n\nexport interface CheckoutReactivationCopy {\n  readonly title: string\n  readonly titleAnnual: string\n  /** Bodies carry `{plan} {date} {newPlan} {nextDate} {amount}` tokens. */\n  readonly upgradeBody: string\n  readonly downgradeBody: string\n  readonly durationChangeBody: string\n  readonly durationChangeBodyMonthly: string\n  /** The same bodies without the renewal clause, for a quote with no renewal date. */\n  readonly withoutRenewalDate: {\n    readonly upgradeBody: string\n    readonly downgradeBody: string\n    readonly durationChangeBody: string\n    readonly durationChangeBodyMonthly: string\n  }\n  readonly confirmButton: string\n  readonly confirmButtonWithCharge: (amount: string) => string\n  readonly checkboxLabel: (amount: string) => string\n}\n\nexport interface CheckoutCopy {\n  readonly back: string\n  readonly usdPerMonth: string\n  readonly billedMonthly: string\n  readonly billedYearly: (total: string) => string\n  readonly eachMonthCreditsRefill: string\n  readonly eachYearCreditsRefill: string\n  readonly totalDueToday: string\n  readonly renewsAt: (amount: string, date: string) => string\n  readonly renewsAtAmount: (amount: string) => string\n  readonly discount: Readonly<Record<DiscountKind, string>>\n  readonly promoCodePlaceholder: string\n  readonly applyPromoCode: string\n  readonly reconciliationTitle: string\n  readonly reconciliationDetail: string\n  readonly authenticationFailedDetail: string\n  readonly pendingVerificationDetail: string\n  readonly completeVerification: string\n  readonly cancelPaymentAndRetry: string\n  readonly confirmPayment: string\n  readonly startingToday: string\n  readonly parkedCheckoutDetail: string\n  readonly completePayment: string\n  readonly payAndSubscribe: string\n  readonly subscribeToPlan: (plan: string) => string\n  readonly confirmUpgradeTitle: string\n  readonly confirmChangeTitle: string\n  readonly switchesToday: string\n  readonly startsOn: (date: string) => string\n  readonly creditsYoullGetToday: string\n  readonly refillReplacesNote: string\n  readonly afterThat: string\n  readonly creditsRefillMonthlyTo: string\n  readonly billedEachMonth: (amount: string) => string\n  readonly discountComposition: string\n  readonly quoteUnavailable: string\n  readonly confirmUpgradeCta: string\n  readonly confirmChange: string\n  readonly reactivation: CheckoutReactivationCopy\n  readonly savedMethod: CheckoutSavedMethodCopy\n  readonly terms: CheckoutTermsCopy\n  readonly payment: StripePaymentCopy\n}\n\nexport interface CheckoutSuccessCopy {\n  readonly allSet: string\n  readonly planUpdated: string\n  readonly receiptEmailed: string\n  readonly usdPerMonth: string\n  readonly usdPerYear: string\n  readonly perMonth: string\n  readonly perYear: string\n  readonly promoApplied: (code: string) => string\n  readonly promoRenews: (amount: string, date: string) => string\n  readonly close: string\n}\n\nexport interface CheckoutInviteCopy {\n  readonly title: string\n  readonly subtext: string\n  readonly placeholder: string\n  readonly sendInvites: string\n  readonly removeTag: string\n  readonly invalidEmailCount: (count: number) => string\n  readonly pendingInviteSingle: string\n  readonly pendingInviteCount: (count: number) => string\n  readonly seatLimitExceeded: (max: number, overage: number) => string\n  readonly invitedMessage: (emails: string, count: number) => string\n  readonly failedCount: (count: number) => string\n}\n\nexport type CopySegment<Key extends string> =\n  | { readonly kind: 'text'; readonly text: string }\n  | { readonly kind: 'slot'; readonly key: Key }\n\n/**\n * Splits `text` at each `{key}` so a template can render the surrounding\n * prose as text and each placeholder as its own element.\n */\nexport function splitPlaceholders<Key extends string>(\n  text: string,\n  keys: readonly Key[]\n): CopySegment<Key>[] {\n  const pattern = new RegExp(`\\\\{(${keys.join('|')})\\\\}`, 'g')\n  const segments: CopySegment<Key>[] = []\n  let cursor = 0\n  for (const match of text.matchAll(pattern)) {\n    if (match.index > cursor) {\n      segments.push({ kind: 'text', text: text.slice(cursor, match.index) })\n    }\n    const key = keys.find((candidate) => candidate === match[1])\n    if (key !== undefined) segments.push({ kind: 'slot', key })\n    cursor = match.index + match[0].length\n  }\n  if (cursor < text.length) {\n    segments.push({ kind: 'text', text: text.slice(cursor) })\n  }\n  return segments\n}\n","<template>\n  <p class=\"m-0 text-center text-xs text-muted-foreground\">\n    <span>\n      <template v-for=\"(segment, index) in segments\" :key=\"index\">\n        <template v-if=\"segment.kind === 'text'\">{{ segment.text }}</template>\n        <a\n          v-else\n          :href=\"LINKS[segment.key]\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n          class=\"underline hover:text-base-foreground\"\n        >\n          {{ segment.key === 'terms' ? copy.terms : copy.privacyPolicy }}\n        </a>\n      </template>\n    </span>\n  </p>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport type { CheckoutTermsCopy } from './checkoutCopy'\nimport { splitPlaceholders } from './checkoutCopy'\n\nconst { copy } = defineProps<{ copy: CheckoutTermsCopy }>()\n\nconst LINKS = {\n  terms: 'https://comfy.org/terms-of-service/',\n  privacy: 'https://comfy.org/privacy-policy/'\n} as const\n\nconst segments = computed(() =>\n  splitPlaceholders(copy.agreement, ['terms', 'privacy'] as const)\n)\n</script>\n","<template>\n  <p role=\"status\" class=\"m-0 text-sm text-muted-foreground\">\n    {{ copy.pendingVerificationDetail }}\n  </p>\n  <CheckoutButton\n    variant=\"inverted\"\n    size=\"lg\"\n    class=\"w-full rounded-lg\"\n    @click=\"openVerification\"\n  >\n    {{ copy.completeVerification }}\n  </CheckoutButton>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * A pending 3DS verification is the only actionable step, so it leads the\n * footer and opens the bank's page in a new tab.\n */\nimport CheckoutButton from './CheckoutButton.vue'\nimport type { CheckoutCopy } from './checkoutCopy'\n\nconst { actionUrl, copy } = defineProps<{\n  actionUrl: string\n  copy: Pick<CheckoutCopy, 'pendingVerificationDetail' | 'completeVerification'>\n}>()\n\nfunction openVerification() {\n  window.open(actionUrl, '_blank', 'noopener,noreferrer')\n}\n</script>\n","<template>\n  <CheckoutPaymentNotices\n    :embedded-checkout-enabled\n    :reconciliation-operation-id\n    :authentication-state\n    :authentication-error\n    :copy\n  />\n\n  <div v-if=\"payAction === 'parked'\" class=\"flex flex-col gap-2\">\n    <div\n      role=\"alert\"\n      class=\"rounded-lg border border-interface-stroke bg-secondary-background p-4 text-sm text-base-foreground\"\n    >\n      {{ copy.parkedCheckoutDetail }}\n    </div>\n    <CheckoutButton\n      variant=\"inverted\"\n      size=\"lg\"\n      class=\"w-full rounded-lg\"\n      :loading=\"isLoading\"\n      :disabled=\"payDisabled\"\n      @click=\"emit('addCreditCard')\"\n    >\n      {{ copy.completePayment }}\n    </CheckoutButton>\n  </div>\n\n  <CheckoutVerificationPrompt\n    v-if=\"verificationUrl\"\n    :action-url=\"verificationUrl\"\n    :copy\n  />\n\n  <CheckoutPaymentForm\n    v-if=\"payAction === 'form' && previewData\"\n    :key=\"`${previewData.quote_id}:${previewData.quote_version}`\"\n    :publishable-key\n    :amount-cents=\"previewData.amount_due_cents ?? 0\"\n    :currency=\"previewData.currency ?? ''\"\n    :copy=\"copy.payment\"\n    :submit-label=\"copy.payAndSubscribe\"\n    :payment-method-configuration-id=\"\n      previewData.payment_method_configuration_id ?? ''\n    \"\n    :is-loading\n    :verification-pending\n    :can-submit=\"quoteIsCurrent\"\n    :theme-key\n    @submitting-change=\"emit('submittingChange', $event)\"\n    @confirm=\"(token, methodType) => emit('confirmPayment', token, methodType)\"\n    @phase=\"emit('paymentPhase', $event)\"\n  />\n\n  <CheckoutButton\n    v-if=\"payAction === 'pay' || payAction === 'subscribe'\"\n    :variant=\"payAction === 'pay' ? 'inverted' : 'tertiary'\"\n    size=\"lg\"\n    class=\"w-full rounded-lg\"\n    :loading=\"isLoading\"\n    :disabled=\"payDisabled\"\n    @click=\"emit('addCreditCard')\"\n  >\n    {{\n      payAction === 'pay'\n        ? copy.payAndSubscribe\n        : copy.subscribeToPlan(planName)\n    }}\n  </CheckoutButton>\n\n  <CheckoutTermsNote class=\"mt-2\" :copy=\"copy.terms\" />\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The new-subscription confirm's pay column: what an earlier attempt left to\n * read or finish, then the one way to pay `payAction` names, then the terms.\n */\nimport type {\n  BillingAuthenticationState,\n  SubscriptionPreview\n} from '@comfyorg/account-core/billing'\n\nimport type { StripePaymentPhase } from '../stripe/stripePaymentPhase'\nimport CheckoutButton from './CheckoutButton.vue'\nimport CheckoutPaymentForm from './CheckoutPaymentForm.vue'\nimport CheckoutPaymentNotices from './CheckoutPaymentNotices.vue'\nimport CheckoutTermsNote from './CheckoutTermsNote.vue'\nimport CheckoutVerificationPrompt from './CheckoutVerificationPrompt.vue'\nimport type { CheckoutCopy } from './checkoutCopy'\nimport type { CheckoutPayAction } from './checkoutRecovery'\n\nconst {\n  payAction,\n  copy,\n  planName,\n  previewData,\n  publishableKey,\n  themeKey,\n  isLoading,\n  payDisabled,\n  verificationUrl,\n  verificationPending,\n  quoteIsCurrent,\n  embeddedCheckoutEnabled,\n  reconciliationOperationId,\n  authenticationState,\n  authenticationError\n} = defineProps<{\n  payAction: CheckoutPayAction\n  copy: CheckoutCopy\n  planName: string\n  previewData: SubscriptionPreview | null\n  publishableKey: string\n  themeKey?: string\n  isLoading: boolean\n  payDisabled: boolean\n  /** Set while a 3DS verification is on offer. */\n  verificationUrl: string | null\n  verificationPending: boolean\n  quoteIsCurrent: boolean\n  embeddedCheckoutEnabled: boolean\n  reconciliationOperationId: string | null\n  authenticationState: BillingAuthenticationState | null\n  authenticationError: string | null\n}>()\n\nconst emit = defineEmits<{\n  addCreditCard: []\n  confirmPayment: [confirmationToken: string, paymentMethodType: string]\n  submittingChange: [submitting: boolean]\n  paymentPhase: [phase: StripePaymentPhase]\n}>()\n</script>\n","<template>\n  <div class=\"flex flex-col gap-2\">\n    <span class=\"text-sm text-base-foreground\">\n      {{ plan.name }}\n    </span>\n    <div class=\"flex items-baseline gap-2\">\n      <span class=\"text-2xl font-semibold text-base-foreground tabular-nums\">\n        ${{ displayPrice }}\n      </span>\n      <span class=\"text-base text-base-foreground\">\n        {{ copy.usdPerMonth }}\n      </span>\n    </div>\n    <span class=\"text-muted-foreground\">\n      {{ billedLabel }}\n    </span>\n    <span class=\"text-muted-foreground\">\n      {{ copy.startingToday }}\n    </span>\n  </div>\n\n  <div\n    :class=\"cn('flex flex-col gap-3 pt-16 pb-8', compact && 'xl:pt-6 xl:pb-4')\"\n  >\n    <div class=\"flex items-center justify-between\">\n      <span class=\"text-base-foreground\">\n        {{ refillLabel }}\n      </span>\n      <div class=\"flex items-center gap-1\">\n        <i class=\"icon-[lucide--coins] size-4 shrink-0 bg-credit\" />\n        <span class=\"font-bold text-base-foreground tabular-nums\">\n          {{ refillCredits }}\n        </span>\n      </div>\n    </div>\n  </div>\n\n  <div\n    v-if=\"totalDueToday\"\n    :class=\"\n      cn(\n        'flex flex-col gap-2 border-t border-border-subtle pt-8',\n        compact && 'xl:pt-6'\n      )\n    \"\n  >\n    <div class=\"flex items-center justify-between text-base\">\n      <span class=\"text-base-foreground\">\n        {{ copy.totalDueToday }}\n      </span>\n      <span class=\"font-bold text-base-foreground tabular-nums\">\n        {{ totalDueToday }}\n      </span>\n    </div>\n    <span class=\"text-sm text-muted-foreground\">\n      {{ renewalTerms }}\n    </span>\n  </div>\n  <div v-if=\"discounts.length\" class=\"flex flex-col gap-2 pt-4 text-sm\">\n    <div\n      v-for=\"discount in discounts\"\n      :key=\"discount.key\"\n      class=\"flex items-center justify-between text-muted-foreground\"\n    >\n      <span>{{ discount.label }}</span>\n      <span class=\"text-base-foreground\">\n        {{ discount.name\n        }}<template v-if=\"discount.amount\"> · −{{ discount.amount }}</template>\n      </span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The new-subscription confirm's money block: the plan and its price, the\n * credits a period refills, today's charge with the renewal terms, and the\n * discounts the quote applied.\n */\nimport { computed } from 'vue'\n\nimport type { SubscriptionPreview } from '@comfyorg/account-core/billing'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport type { CheckoutCopy } from './checkoutCopy'\nimport type { CheckoutBillingCycle, CheckoutPlan } from './checkoutQuote'\nimport {\n  formatAmountDueToday,\n  formatNumber,\n  formatQuoteMoney,\n  formatRenewalAmount,\n  isYearlyCheckout,\n  resolveRenewalDate\n} from './checkoutQuote'\n\nconst {\n  plan,\n  copy,\n  locale,\n  previewData,\n  billingCycle,\n  compact = false\n} = defineProps<{\n  plan: CheckoutPlan\n  copy: CheckoutCopy\n  locale: string\n  previewData: SubscriptionPreview | null\n  billingCycle: CheckoutBillingCycle\n  /** The embedded card form sits beside the summary, so it tightens up. */\n  compact?: boolean\n}>()\n\nconst isYearly = computed(() =>\n  isYearlyCheckout(previewData?.new_plan.duration, billingCycle)\n)\nconst quotedPrice = computed(() =>\n  plan.pricedByQuote ? previewData?.new_plan : undefined\n)\n\nconst displayPrice = computed(() => {\n  if (quotedPrice.value) {\n    const cents = quotedPrice.value.price_cents\n    return ((isYearly.value ? cents / 12 : cents) / 100).toFixed(0)\n  }\n  return formatNumber(\n    isYearly.value ? plan.monthlyPriceUsd.yearly : plan.monthlyPriceUsd.monthly,\n    locale\n  )\n})\n\nconst billedLabel = computed(() => {\n  if (!isYearly.value) return copy.billedMonthly\n  const usd = quotedPrice.value\n    ? quotedPrice.value.price_cents / 100\n    : plan.monthlyPriceUsd.yearly * 12\n  return copy.billedYearly(`$${formatNumber(usd, locale)}`)\n})\n\nconst refillLabel = computed(() =>\n  isYearly.value ? copy.eachYearCreditsRefill : copy.eachMonthCreditsRefill\n)\n\nconst refillCredits = computed(() =>\n  formatNumber(\n    isYearly.value ? plan.monthlyCredits * 12 : plan.monthlyCredits,\n    locale\n  )\n)\n\nconst totalDueToday = computed(() =>\n  previewData ? formatAmountDueToday(previewData, locale) : ''\n)\n\nconst renewalTerms = computed(() => {\n  if (!previewData) return ''\n  const amount = formatRenewalAmount(previewData, locale)\n  if (!amount) return ''\n  const renewsAt = resolveRenewalDate(previewData)\n  if (!renewsAt) return copy.renewsAtAmount(amount)\n  const date = new Date(renewsAt).toLocaleDateString(locale, {\n    month: 'short',\n    day: 'numeric',\n    year: 'numeric',\n    timeZone: 'UTC'\n  })\n  return copy.renewsAt(amount, date)\n})\n\nconst discounts = computed(() =>\n  (previewData?.discounts ?? []).map((discount) => ({\n    key: `${discount.kind}:${discount.code}`,\n    label: copy.discount[discount.kind],\n    name: discount.name || discount.code,\n    amount: discount.amount_off_cents\n      ? formatQuoteMoney(\n          discount.amount_off_cents,\n          previewData?.currency,\n          locale\n        )\n      : ''\n  }))\n)\n</script>\n","import type { BillingAuthenticationState } from '@comfyorg/account-core/billing'\n\nexport interface CheckoutRecoveryState {\n  readonly actionUrl: string | null\n  readonly authenticationState: BillingAuthenticationState | null\n  readonly reconciliationOperationId: string | null\n  readonly embeddedCheckoutEnabled: boolean\n}\n\n/** A 3DS link is on offer unless the last attempt at it already failed. */\nexport function isVerificationOffered({\n  actionUrl,\n  authenticationState\n}: CheckoutRecoveryState): boolean {\n  return Boolean(actionUrl) && authenticationState !== 'failed_retryable'\n}\n\n/**\n * While an earlier payment still needs the customer (a verification to\n * finish, a failed one to retry, or a charge awaiting reconciliation), the\n * pay action stays disabled so a second charge cannot start beside it.\n */\nexport function isVerificationRecoveryActive(\n  state: CheckoutRecoveryState\n): boolean {\n  return (\n    isVerificationOffered(state) ||\n    (state.embeddedCheckoutEnabled &&\n      (state.authenticationState === 'requires_action' ||\n        state.authenticationState === 'failed_retryable' ||\n        Boolean(state.reconciliationOperationId)))\n  )\n}\n\n/**\n * `parked`: complete the checkout an earlier subscribe left waiting;\n * `form`: the card form; `pay`: pay without it (saved method, $0 or an\n * unidentified quote); `subscribe`: hand off to a hosted continuation.\n */\nexport type CheckoutPayAction = 'parked' | 'form' | 'pay' | 'subscribe'\n","<template>\n  <div :class=\"layout.root\">\n    <div :class=\"layout.summary\">\n      <div :class=\"layout.header\">\n        <CheckoutButton\n          size=\"icon\"\n          variant=\"muted-textonly\"\n          class=\"shrink-0 rounded-full\"\n          :aria-label=\"copy.back\"\n          :disabled=\"interactionLocked\"\n          @click=\"emit('back')\"\n        >\n          <i class=\"pi pi-arrow-left text-base\" />\n        </CheckoutButton>\n        <h2 :class=\"layout.title\">\n          {{ copy.confirmPayment }}\n        </h2>\n      </div>\n      <slot v-if=\"summaryReplaced\" name=\"summary\" />\n      <template v-else>\n        <CheckoutSubscribeSummary\n          :plan\n          :copy\n          :locale\n          :preview-data\n          :billing-cycle\n          :compact=\"usePaymentElement\"\n        />\n        <CheckoutPromotionCode\n          v-if=\"embeddedCheckoutEnabled\"\n          :applied-code=\"previewData?.promotion_code\"\n          :disabled=\"interactionLocked\"\n          :copy\n          @apply=\"emit('applyPromotionCode', $event)\"\n          @invalidate=\"emit('invalidateQuote')\"\n        />\n      </template>\n      <CheckoutSavedMethods\n        v-if=\"showSavedMethods && savedMethods\"\n        v-model:selected-method-id=\"selectedSavedMethodId\"\n        :methods=\"savedMethods\"\n        :copy=\"copy.savedMethod\"\n        @change-payment-method=\"emit('changePaymentMethod')\"\n      />\n    </div>\n\n    <div :class=\"layout.footer\">\n      <CheckoutSubscribeActions\n        :pay-action\n        :copy\n        :plan-name=\"plan.name\"\n        :preview-data\n        :publishable-key\n        :theme-key\n        :is-loading\n        :pay-disabled\n        :verification-url=\"verificationOffered ? actionUrl : null\"\n        :verification-pending=\"Boolean(actionUrl) || verificationRecoveryActive\"\n        :quote-is-current\n        :embedded-checkout-enabled\n        :reconciliation-operation-id\n        :authentication-state\n        :authentication-error\n        @add-credit-card=\"emit('addCreditCard')\"\n        @confirm-payment=\"(token, type) => emit('confirmPayment', token, type)\"\n        @submitting-change=\"stripeSubmissionPending = $event\"\n        @payment-phase=\"emit('paymentPhase', $event)\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The confirm step of a new subscription: the plan and today's charge on one\n * side, and the way to pay on the other — the card form, the saved methods\n * that stand in for it, or a hosted continuation the host opens. A host\n * following a payment it did not quote here replaces the plan and charge\n * through the `summary` slot and `summaryReplaced`.\n */\nimport { computed, ref } from 'vue'\n\nimport type {\n  BillingAuthenticationState,\n  SavedPaymentMethod,\n  SubscriptionPreview\n} from '@comfyorg/account-core/billing'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport type { StripePaymentPhase } from '../stripe/stripePaymentPhase'\nimport CheckoutButton from './CheckoutButton.vue'\nimport CheckoutPromotionCode from './CheckoutPromotionCode.vue'\nimport CheckoutSavedMethods from './CheckoutSavedMethods.vue'\nimport CheckoutSubscribeActions from './CheckoutSubscribeActions.vue'\nimport CheckoutSubscribeSummary from './CheckoutSubscribeSummary.vue'\nimport type { CheckoutCopy } from './checkoutCopy'\nimport type { CheckoutBillingCycle, CheckoutPlan } from './checkoutQuote'\nimport type { CheckoutPayAction } from './checkoutRecovery'\nimport {\n  isVerificationOffered,\n  isVerificationRecoveryActive\n} from './checkoutRecovery'\n\nconst {\n  plan,\n  copy,\n  locale,\n  publishableKey,\n  themeKey,\n  billingCycle = 'monthly',\n  isLoading = false,\n  previewData = null,\n  actionUrl = null,\n  authenticationState = null,\n  authenticationError = null,\n  reconciliationOperationId = null,\n  parkedCheckoutRecovery = false,\n  usePaymentElement = false,\n  savedMethods = null,\n  quoteIsCurrent = false,\n  isApplyingPromotionCode = false,\n  embeddedCheckoutEnabled = false,\n  summaryReplaced = false\n} = defineProps<{\n  plan: CheckoutPlan\n  copy: CheckoutCopy\n  locale: string\n  publishableKey: string\n  themeKey?: string\n  billingCycle?: CheckoutBillingCycle\n  isLoading?: boolean\n  previewData?: SubscriptionPreview | null\n  actionUrl?: string | null\n  authenticationState?: BillingAuthenticationState | null\n  authenticationError?: string | null\n  reconciliationOperationId?: string | null\n  /** Subscribe landed on a checkout already waiting for a card; only another\n   *  subscribe can re-issue its payment link. */\n  parkedCheckoutRecovery?: boolean\n  usePaymentElement?: boolean\n  /** When present the card form is skipped and the confirm renders as one\n   *  narrow column. */\n  savedMethods?: readonly SavedPaymentMethod[] | null\n  quoteIsCurrent?: boolean\n  isApplyingPromotionCode?: boolean\n  embeddedCheckoutEnabled?: boolean\n  /** The host summarizes a payment it did not quote here in the `summary` slot. */\n  summaryReplaced?: boolean\n}>()\n\nconst emit = defineEmits<{\n  addCreditCard: []\n  confirmPayment: [confirmationToken: string, paymentMethodType: string]\n  back: []\n  changePaymentMethod: []\n  applyPromotionCode: [code: string]\n  invalidateQuote: []\n  paymentPhase: [phase: StripePaymentPhase]\n}>()\n\nconst selectedSavedMethodId = defineModel<string | null>(\n  'selectedSavedMethodId',\n  { default: null }\n)\n\n// The wide capture split only applies while a payment method is being\n// collected; with a saved method the confirm is a single narrow column.\nconst captureMode = computed(() => usePaymentElement && !savedMethods?.length)\nconst showSavedMethods = computed(\n  () => embeddedCheckoutEnabled && Boolean(savedMethods?.length)\n)\n\nconst layout = computed(() => {\n  const split = captureMode.value\n  return {\n    root: cn(\n      'mx-auto flex h-full min-h-0 max-w-[400px] flex-col items-stretch justify-between overflow-y-auto text-sm motion-safe:animate-in motion-safe:duration-300 motion-safe:fade-in motion-safe:slide-in-from-bottom-2',\n      // Edge-to-edge Stripe-checkout split on desktop: the summary is a\n      // flush full-height sidebar on base-background, payment beside it on\n      // the shell. Mobile keeps the stacked flow.\n      split &&\n        'xl:min-h-0 xl:w-full xl:max-w-none xl:flex-1 xl:flex-row xl:items-stretch xl:gap-0 xl:overflow-visible'\n    ),\n    summary: cn(\n      split &&\n        'xl:w-[42%] xl:shrink-0 xl:border-r xl:border-border-subtle xl:bg-base-background xl:px-12 xl:py-10',\n      // Below xl the same dual tone runs vertically: the summary bleeds\n      // dark to the dialog edges, payment continues on the shell below.\n      split &&\n        'max-xl:-mx-4 max-xl:-mt-6 max-xl:rounded-t-2xl max-xl:bg-base-background max-xl:p-6'\n    ),\n    header: cn('mb-8 flex items-center gap-3', split && 'xl:mb-10'),\n    title: cn(\n      'm-0 flex-1 text-center text-xl font-semibold text-base-foreground lg:text-2xl',\n      // In the sidebar the title goes quiet and the money block leads.\n      split &&\n        'xl:text-left xl:text-base xl:font-medium xl:text-muted-foreground'\n    ),\n    footer: cn(\n      'flex flex-col gap-2 pt-8 pb-4',\n      split && 'xl:min-h-0 xl:min-w-0 xl:flex-1 xl:px-16 xl:py-10',\n      // Match the summary panel's 24px edge inset (root p-4 provides 16).\n      split && 'max-xl:px-2'\n    )\n  }\n})\n\nconst amountDueCents = computed(() => previewData?.amount_due_cents ?? 0)\n// Stripe Elements are configured once, on mount, from the amount and\n// currency. Mounting before the quote arrives permanently latches the\n// \"payment options are unavailable\" error, because nothing re-initializes\n// the element when the props later fill in.\nconst quoteReady = computed(\n  () =>\n    amountDueCents.value > 0 &&\n    Boolean(previewData?.currency) &&\n    Boolean(previewData?.quote_id) &&\n    previewData?.quote_version !== undefined\n)\nconst recoveryState = computed(() => ({\n  actionUrl,\n  authenticationState,\n  reconciliationOperationId,\n  embeddedCheckoutEnabled\n}))\nconst verificationOffered = computed(() =>\n  isVerificationOffered(recoveryState.value)\n)\nconst verificationRecoveryActive = computed(() =>\n  isVerificationRecoveryActive(recoveryState.value)\n)\nconst quoteIsUsable = computed(() => !embeddedCheckoutEnabled || quoteIsCurrent)\n\nconst stripeSubmissionPending = ref(false)\nconst interactionLocked = computed(\n  () => isLoading || isApplyingPromotionCode || stripeSubmissionPending.value\n)\nconst payAction = computed<CheckoutPayAction>(() => {\n  if (parkedCheckoutRecovery) return 'parked'\n  if (captureMode.value) return quoteReady.value ? 'form' : 'pay'\n  return savedMethods?.length ? 'pay' : 'subscribe'\n})\n\nconst payDisabled = computed(\n  () =>\n    interactionLocked.value ||\n    !quoteIsUsable.value ||\n    verificationRecoveryActive.value\n)\n</script>\n","<template>\n  <div\n    class=\"mx-auto flex h-full min-h-0 max-w-[400px] flex-col items-stretch justify-between overflow-y-auto text-sm motion-safe:animate-in motion-safe:duration-300 motion-safe:fade-in motion-safe:slide-in-from-bottom-2\"\n  >\n    <div class=\"flex flex-col items-center gap-4 pt-8\">\n      <i class=\"pi pi-check-circle text-5xl text-success-background\" />\n      <h2\n        class=\"m-0 text-center text-xl font-semibold text-base-foreground lg:text-2xl\"\n      >\n        {{ copy.allSet }}\n      </h2>\n      <p class=\"m-0 text-center text-sm text-muted-foreground\">\n        {{ copy.planUpdated }}\n        {{ copy.receiptEmailed }}\n      </p>\n\n      <slot v-if=\"planReplaced\" name=\"plan\" />\n      <template v-else>\n        <div\n          :class=\"\n            cn(\n              'mt-4 flex w-full flex-col gap-1 rounded-xl border border-border-default bg-base-background p-4',\n              darkSurface && 'border-none bg-secondary-background'\n            )\n          \"\n        >\n          <span class=\"text-sm text-base-foreground\">{{ plan.name }}</span>\n          <div class=\"flex items-baseline gap-1\">\n            <span\n              class=\"text-2xl font-semibold text-base-foreground tabular-nums\"\n            >\n              ${{ displayPrice }}\n            </span>\n            <span class=\"text-sm text-base-foreground\">\n              {{ isYearly ? copy.usdPerYear : copy.usdPerMonth }}\n            </span>\n          </div>\n          <div class=\"flex items-center gap-1 text-sm text-muted-foreground\">\n            <i class=\"icon-[lucide--coins] size-4 shrink-0 bg-credit\" />\n            <span class=\"tabular-nums\">\n              {{ displayCredits }} {{ isYearly ? copy.perYear : copy.perMonth }}\n            </span>\n          </div>\n        </div>\n\n        <p\n          v-if=\"promoApplied\"\n          class=\"m-0 text-center text-sm text-muted-foreground tabular-nums\"\n        >\n          <span class=\"font-medium text-base-foreground\">\n            {{ copy.promoApplied(promoApplied.code) }}\n          </span>\n          {{\n            copy.promoRenews(\n              promoApplied.renewalAmount,\n              promoApplied.renewalDate\n            )\n          }}\n        </p>\n      </template>\n\n      <slot name=\"details\" />\n    </div>\n\n    <div class=\"flex flex-col gap-2 pt-8 pb-4\">\n      <slot name=\"actions\" />\n      <CheckoutButton\n        :variant=\"closeDemoted ? 'muted-textonly' : 'secondary'\"\n        size=\"lg\"\n        class=\"w-full rounded-lg\"\n        @click=\"emit('close')\"\n      >\n        {{ copy.close }}\n      </CheckoutButton>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The step after a successful subscribe: what the customer now has. A host\n * adds its own follow-up (the cloud app's team invite) through the\n * `details` and `actions` slots, demoting Close when it leads with another\n * action, and names a plan it did not quote here through the `plan` slot and\n * `planReplaced`.\n */\nimport { computed } from 'vue'\n\nimport type { SubscriptionPreview } from '@comfyorg/account-core/billing'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport CheckoutButton from './CheckoutButton.vue'\nimport type { CheckoutSuccessCopy } from './checkoutCopy'\nimport type { CheckoutBillingCycle, CheckoutPlan } from './checkoutQuote'\nimport { formatNumber, isYearlyCheckout } from './checkoutQuote'\n\nconst {\n  plan,\n  copy,\n  locale,\n  previewData = null,\n  billingCycle = 'monthly',\n  darkSurface = false,\n  promoApplied = null,\n  closeDemoted = false,\n  planReplaced = false\n} = defineProps<{\n  plan: CheckoutPlan\n  copy: CheckoutSuccessCopy\n  locale: string\n  previewData?: SubscriptionPreview | null\n  billingCycle?: CheckoutBillingCycle\n  /** The surface paints base-background; the plan card elevates to stay\n   *  visible. */\n  darkSurface?: boolean\n  /** Applied promotion feedback (Figma 5379-30077 S3), display-ready. */\n  promoApplied?: {\n    code: string\n    renewalAmount: string\n    renewalDate: string\n  } | null\n  closeDemoted?: boolean\n  /** The host names a plan it did not quote here in the `plan` slot. */\n  planReplaced?: boolean\n}>()\n\nconst emit = defineEmits<{\n  close: []\n}>()\n\nconst isYearly = computed(() =>\n  isYearlyCheckout(previewData?.new_plan?.duration, billingCycle)\n)\n\nconst displayPrice = computed(() => {\n  if (previewData?.new_plan) {\n    return (previewData.new_plan.price_cents / 100).toFixed(0)\n  }\n  if (plan.pricedByQuote) return '0'\n  return String(\n    isYearly.value\n      ? plan.monthlyPriceUsd.yearly * 12\n      : plan.monthlyPriceUsd.monthly\n  )\n})\n\nconst displayCredits = computed(() =>\n  formatNumber(\n    isYearly.value ? plan.monthlyCredits * 12 : plan.monthlyCredits,\n    locale\n  )\n)\n</script>\n","<template>\n  <div\n    class=\"mb-6 flex gap-3 rounded-2xl border border-warning-background bg-warning-background/20 p-4\"\n  >\n    <div\n      class=\"flex size-8 shrink-0 items-center justify-center rounded-full text-warning-background\"\n    >\n      <i class=\"pi pi-info-circle\" />\n    </div>\n    <div class=\"flex flex-col gap-2\">\n      <p class=\"m-0 text-sm font-bold text-base-foreground\">\n        {{ title }}\n      </p>\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        <span>\n          <template v-for=\"(segment, index) in segments\" :key=\"index\">\n            <span v-if=\"segment.emphasis\" :class=\"amountClass\">{{\n              segment.text\n            }}</span>\n            <template v-else>{{ segment.text }}</template>\n          </template>\n        </span>\n      </p>\n      <label\n        v-if=\"checkboxLabel\"\n        class=\"flex items-center gap-2 pt-1 text-sm text-muted-foreground\"\n      >\n        <input\n          v-model=\"confirmed\"\n          type=\"checkbox\"\n          class=\"size-4 rounded-sm border-interface-stroke\"\n        />\n        {{ checkboxLabel }}\n      </label>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The plan-change confirm's disclosure that the change reactivates a\n * subscription set to end. A charge above the current monthly price is\n * emphasised and has to be acknowledged (`checkboxLabel` set).\n */\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { title, segments, checkboxLabel } = defineProps<{\n  title: string\n  /** The body, with the charge marked for emphasis. */\n  segments: readonly { text: string; emphasis: boolean }[]\n  checkboxLabel: string | null\n}>()\n\nconst confirmed = defineModel<boolean>('confirmed', { required: true })\n\nconst amountClass = computed(() =>\n  cn(\n    'font-bold text-base-foreground',\n    checkboxLabel !== null && 'text-base font-extrabold'\n  )\n)\n</script>\n","<template>\n  <div class=\"flex flex-col gap-2\">\n    <span class=\"text-sm font-semibold text-base-foreground\">\n      {{ planName }}\n    </span>\n    <div class=\"flex items-baseline gap-2\">\n      <span class=\"text-2xl font-semibold text-base-foreground tabular-nums\">\n        ${{ heroPrice }}\n      </span>\n      <span class=\"text-base text-base-foreground\">\n        {{ usdPerMonth }}\n      </span>\n    </div>\n    <span v-for=\"line in details\" :key=\"line\" class=\"text-muted-foreground\">\n      {{ line }}\n    </span>\n  </div>\n\n  <div class=\"flex flex-col gap-2 pt-10\">\n    <span\n      v-if=\"heading\"\n      class=\"text-xs font-semibold tracking-wide text-muted-foreground uppercase\"\n    >\n      {{ heading }}\n    </span>\n    <div class=\"flex items-center justify-between\">\n      <span class=\"text-base-foreground\">{{ refillLabel }}</span>\n      <div class=\"flex items-center gap-1\">\n        <i class=\"icon-[lucide--coins] size-4 shrink-0 bg-credit\" />\n        <span class=\"font-bold text-base-foreground tabular-nums\">{{\n          refillCredits\n        }}</span>\n      </div>\n    </div>\n    <span v-if=\"note\" class=\"text-sm text-muted-foreground\">\n      {{ note }}\n    </span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The plan-change confirm's plan block: the plan switched to, when it takes\n * effect, and the credits it refills — with the \"after that\" heading a\n * scheduled change carries.\n */\nconst {\n  planName,\n  heroPrice,\n  usdPerMonth,\n  details,\n  heading = '',\n  refillLabel,\n  refillCredits,\n  note = ''\n} = defineProps<{\n  planName: string\n  heroPrice: string\n  usdPerMonth: string\n  details: readonly string[]\n  heading?: string\n  refillLabel: string\n  refillCredits: string\n  note?: string\n}>()\n</script>\n","<template>\n  <!-- Immediate changes carry their addends: one sum under one divider\n       (Figma 5344-35724). -->\n  <div\n    :class=\"\n      cn(\n        'flex flex-col gap-2 border-t border-border-subtle pt-6',\n        scheduled && 'mt-10'\n      )\n    \"\n  >\n    <template v-if=\"discounts.length\">\n      <div class=\"flex items-center justify-between text-muted-foreground\">\n        <span>{{ discountComposition }}</span>\n      </div>\n      <div\n        v-for=\"discount in discounts\"\n        :key=\"discount.key\"\n        class=\"flex items-center justify-between text-muted-foreground\"\n      >\n        <span>{{ discount.label }}</span>\n        <span class=\"text-base-foreground\">\n          {{ discount.name\n          }}<template v-if=\"discount.amount\">\n            · −{{ discount.amount }}</template\n          >\n        </span>\n      </div>\n    </template>\n    <div class=\"flex items-center justify-between text-base\">\n      <span class=\"text-base-foreground\">\n        {{ totalDueToday }}\n      </span>\n      <span class=\"font-bold text-base-foreground tabular-nums\">\n        {{ amountDueToday }}\n      </span>\n    </div>\n    <span class=\"text-sm text-muted-foreground\">{{ renewalTerms }}</span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The plan-change confirm's charge block: the discounts an immediate change\n * applies, today's total, and the renewal terms.\n */\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  discounts,\n  discountComposition,\n  totalDueToday,\n  amountDueToday,\n  renewalTerms,\n  scheduled = false\n} = defineProps<{\n  discounts: readonly {\n    readonly key: string\n    readonly label: string\n    readonly name: string\n    readonly amount: string\n  }[]\n  discountComposition: string\n  totalDueToday: string\n  amountDueToday: string\n  renewalTerms: string\n  /** A change that takes effect later sets its total apart from the plan block. */\n  scheduled?: boolean\n}>()\n</script>\n","<template>\n  <div\n    class=\"mx-auto flex h-full min-h-0 max-w-[400px] flex-col items-stretch justify-between overflow-y-auto text-sm motion-safe:animate-in motion-safe:duration-300 motion-safe:fade-in motion-safe:slide-in-from-bottom-2\"\n  >\n    <div>\n      <div class=\"mb-8 flex items-center gap-3\">\n        <CheckoutButton\n          size=\"icon\"\n          variant=\"muted-textonly\"\n          class=\"shrink-0 rounded-full\"\n          :aria-label=\"copy.back\"\n          :disabled=\"interactionLocked\"\n          @click=\"emit('back')\"\n        >\n          <i class=\"pi pi-arrow-left text-base\" />\n        </CheckoutButton>\n        <h2\n          class=\"m-0 flex-1 text-center text-xl font-semibold text-base-foreground lg:text-2xl\"\n        >\n          {{ confirmTitle }}\n        </h2>\n        <div class=\"size-8 shrink-0\" aria-hidden=\"true\" />\n      </div>\n      <CheckoutReactivationBanner\n        v-if=\"isReactivating\"\n        v-model:confirmed=\"reactivationConfirmed\"\n        :title=\"bannerTitle\"\n        :segments=\"bannerSegments\"\n        :checkbox-label=\"\n          exceedsMonthlyThreshold\n            ? copy.reactivation.checkboxLabel(chargeDisplay)\n            : null\n        \"\n      />\n\n      <slot v-if=\"summaryReplaced\" name=\"summary\" />\n      <template v-else>\n        <CheckoutTransitionSummary\n          :plan-name=\"plan.name\"\n          :hero-price\n          :usd-per-month=\"copy.usdPerMonth\"\n          :details=\"planDetails\"\n          :heading=\"isImmediate ? '' : copy.afterThat\"\n          :refill-label=\"refillLabel\"\n          :refill-credits\n          :note=\"refillNote\"\n        />\n\n        <CheckoutTransitionTotal\n          :discounts\n          :discount-composition=\"copy.discountComposition\"\n          :total-due-today=\"copy.totalDueToday\"\n          :amount-due-today\n          :renewal-terms\n          :scheduled=\"!isImmediate\"\n        />\n        <CheckoutPromotionCode\n          v-if=\"embeddedCheckoutEnabled\"\n          :applied-code=\"previewData.promotion_code\"\n          :disabled=\"interactionLocked\"\n          :copy\n          @apply=\"emit('applyPromotionCode', $event)\"\n          @invalidate=\"emit('invalidateQuote')\"\n        />\n      </template>\n    </div>\n\n    <div class=\"flex flex-col gap-2 pt-8 pb-4\">\n      <CheckoutPaymentNotices\n        :embedded-checkout-enabled\n        :reconciliation-operation-id\n        :authentication-state\n        :authentication-error\n        :copy\n      />\n\n      <CheckoutVerificationPrompt\n        v-if=\"verificationUrl\"\n        :action-url=\"verificationUrl\"\n        :copy\n      />\n\n      <template v-if=\"paymentCancelable\">\n        <CheckoutButton\n          variant=\"secondary\"\n          size=\"lg\"\n          class=\"w-full rounded-lg\"\n          :loading=\"cancelingPayment\"\n          @click=\"emit('cancelPayment')\"\n        >\n          {{ copy.cancelPaymentAndRetry }}\n        </CheckoutButton>\n        <p\n          v-if=\"cancelPaymentError\"\n          role=\"alert\"\n          class=\"m-0 text-sm text-destructive-background\"\n        >\n          {{ cancelPaymentError }}\n        </p>\n      </template>\n\n      <CheckoutButton\n        :variant=\"actionUrl ? 'tertiary' : 'inverted'\"\n        size=\"lg\"\n        class=\"w-full rounded-lg\"\n        :loading=\"isLoading\"\n        :disabled=\"confirmBlocked\"\n        @click=\"emit('confirm', confirmReactivation)\"\n      >\n        {{ confirmCta }}\n      </CheckoutButton>\n\n      <CheckoutTermsNote class=\"mt-2\" :copy=\"copy.terms\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The confirm step of a change to an existing subscription: what it switches\n * to and when, what is charged today, and — for a subscription set to end —\n * the reactivation the change implies, which a large enough charge has to be\n * acknowledged before the confirm unlocks. A host following a payment it did\n * not quote here replaces the plan and charge through the `summary` slot and\n * `summaryReplaced`.\n */\nimport { computed, ref, watch } from 'vue'\n\nimport type {\n  BillingAuthenticationState,\n  SubscriptionPreview\n} from '@comfyorg/account-core/billing'\n\nimport CheckoutButton from './CheckoutButton.vue'\nimport CheckoutPaymentNotices from './CheckoutPaymentNotices.vue'\nimport CheckoutPromotionCode from './CheckoutPromotionCode.vue'\nimport CheckoutReactivationBanner from './CheckoutReactivationBanner.vue'\nimport CheckoutTermsNote from './CheckoutTermsNote.vue'\nimport CheckoutTransitionSummary from './CheckoutTransitionSummary.vue'\nimport CheckoutTransitionTotal from './CheckoutTransitionTotal.vue'\nimport CheckoutVerificationPrompt from './CheckoutVerificationPrompt.vue'\nimport type { CheckoutCopy } from './checkoutCopy'\nimport { splitPlaceholders } from './checkoutCopy'\nimport {\n  formatAmountDueToday,\n  formatNumber,\n  formatRenewalAmount,\n  formatUsdFromCents,\n  isAnnualDuration,\n  resolveRenewalDate\n} from './checkoutQuote'\nimport {\n  isVerificationOffered,\n  isVerificationRecoveryActive\n} from './checkoutRecovery'\n\nconst {\n  previewData,\n  plan,\n  currentPlanName,\n  copy,\n  locale,\n  subscriptionLoaded,\n  subscriptionCancelled = false,\n  subscriptionEndDate = null,\n  isLoading = false,\n  actionUrl = null,\n  forceReactivation = false,\n  authenticationState = null,\n  authenticationError = null,\n  reconciliationOperationId = null,\n  quoteIsCurrent = false,\n  isApplyingPromotionCode = false,\n  embeddedCheckoutEnabled = false,\n  summaryReplaced = false,\n  paymentCancelable = false,\n  cancelingPayment = false,\n  cancelPaymentError = null\n} = defineProps<{\n  previewData: SubscriptionPreview\n  /** The plan switched to: its name and the credits one month refills. All\n   *  proration money stays driven by `previewData`. */\n  plan: { readonly name: string; readonly monthlyCredits: number }\n  currentPlanName: string\n  copy: CheckoutCopy\n  locale: string\n  /** False until the subscription status has loaded once; the confirm stays\n   *  disabled until then. */\n  subscriptionLoaded: boolean\n  subscriptionCancelled?: boolean\n  subscriptionEndDate?: string | Date | null\n  isLoading?: boolean\n  actionUrl?: string | null\n  /** Server-authoritative fallback for legacy status reads that omit a\n   * scheduled cancellation until subscribe enforces the consent gate. */\n  forceReactivation?: boolean\n  authenticationState?: BillingAuthenticationState | null\n  authenticationError?: string | null\n  reconciliationOperationId?: string | null\n  quoteIsCurrent?: boolean\n  isApplyingPromotionCode?: boolean\n  embeddedCheckoutEnabled?: boolean\n  /** The host summarizes a payment it did not quote here in the `summary` slot. */\n  summaryReplaced?: boolean\n  /** The server's `cancelable` for the pending payment; the cancel is offered only on true. */\n  paymentCancelable?: boolean\n  cancelingPayment?: boolean\n  cancelPaymentError?: string | null\n}>()\n\nconst emit = defineEmits<{\n  /** True only once the reactivation banner was shown and confirmed (checkbox\n   *  ticked above the charge threshold, since the button is gated on it). */\n  confirm: [confirmReactivation: boolean]\n  back: []\n  applyPromotionCode: [code: string]\n  invalidateQuote: []\n  cancelPayment: []\n}>()\n\nconst recoveryState = computed(() => ({\n  actionUrl,\n  authenticationState,\n  reconciliationOperationId,\n  embeddedCheckoutEnabled\n}))\nconst verificationUrl = computed(() =>\n  isVerificationOffered(recoveryState.value) ? actionUrl : null\n)\nconst verificationRecoveryActive = computed(() =>\n  isVerificationRecoveryActive(recoveryState.value)\n)\nconst quoteIsUsable = computed(() => !embeddedCheckoutEnabled || quoteIsCurrent)\nconst interactionLocked = computed(() => isLoading || isApplyingPromotionCode)\n\nfunction formatDate(date: string | Date): string {\n  return new Intl.DateTimeFormat('en-US', {\n    month: 'short',\n    day: 'numeric',\n    year: 'numeric',\n    timeZone: 'UTC'\n  }).format(typeof date === 'string' ? new Date(date) : date)\n}\n\nconst isImmediate = computed(() => previewData.is_immediate)\nconst newIsYearly = computed(() =>\n  isAnnualDuration(previewData.new_plan.duration)\n)\nconst currentIsYearly = computed(() =>\n  isAnnualDuration(previewData.current_plan?.duration)\n)\n\nconst isCancelled = computed(\n  () => forceReactivation || (!embeddedCheckoutEnabled && subscriptionCancelled)\n)\n\nconst reactivationVariant = computed<\n  'upgrade' | 'downgrade' | 'duration_change' | null\n>(() => {\n  if (!isCancelled.value) return null\n  switch (previewData.transition_type) {\n    case 'upgrade':\n      return 'upgrade'\n    case 'downgrade':\n      return 'downgrade'\n    case 'duration_change':\n      return 'duration_change'\n    default:\n      return null\n  }\n})\n// The banner and threshold math read the end date and the current plan;\n// without them the banner would render broken copy or force the checkbox on\n// a bogus $0 threshold.\nconst cancelAt = computed(\n  () => subscriptionEndDate ?? previewData.current_plan?.period_end\n)\n\nconst isReactivating = computed(\n  () =>\n    isCancelled.value &&\n    reactivationVariant.value !== null &&\n    !!cancelAt.value &&\n    !!previewData.current_plan\n)\n\n// seat_summary.total_cost_cents is the whole-subscription price; price_cents\n// is per-seat and understates the threshold on multi-seat team plans. ANNUAL\n// divides by 12 for a monthly equivalent.\nconst currentMonthlyPriceCents = computed(() => {\n  const current = previewData.current_plan\n  if (!current) return 0\n  const totalCents = current.seat_summary.total_cost_cents\n  return currentIsYearly.value ? totalCents / 12 : totalCents\n})\nconst chargeCents = computed(\n  () => previewData.amount_due_cents ?? previewData.cost_today_cents\n)\n// The downgrade copy always says \"you won't be charged today\" with no amount\n// shown, so it never gets the checkbox even if cost_today_cents is positive.\nconst exceedsMonthlyThreshold = computed(\n  () =>\n    isReactivating.value &&\n    reactivationVariant.value !== 'downgrade' &&\n    chargeCents.value > currentMonthlyPriceCents.value\n)\nconst chargeDisplay = computed(\n  () => `$${formatUsdFromCents(chargeCents.value)}`\n)\n\nconst reactivationConfirmed = ref(false)\n// A checked box is consent to this exact preview. A replacement preview must\n// not inherit that consent, even when its displayed charge is unchanged.\nwatch(\n  () => previewData,\n  () => {\n    reactivationConfirmed.value = false\n  }\n)\n\nconst confirmDisabled = computed(\n  () =>\n    !subscriptionLoaded ||\n    (exceedsMonthlyThreshold.value && !reactivationConfirmed.value)\n)\nconst confirmBlocked = computed(\n  () =>\n    confirmDisabled.value ||\n    !quoteIsUsable.value ||\n    verificationRecoveryActive.value\n)\nconst confirmReactivation = computed(\n  () =>\n    isReactivating.value &&\n    (!exceedsMonthlyThreshold.value || reactivationConfirmed.value)\n)\n\nconst bannerTitle = computed(() =>\n  reactivationVariant.value === 'duration_change' && newIsYearly.value\n    ? copy.reactivation.titleAnnual\n    : copy.reactivation.title\n)\nconst bannerBody = computed(() => {\n  const bodies =\n    nextPaymentDate.value === undefined\n      ? copy.reactivation.withoutRenewalDate\n      : copy.reactivation\n  switch (reactivationVariant.value) {\n    case 'upgrade':\n      return bodies.upgradeBody\n    case 'downgrade':\n      return bodies.downgradeBody\n    case 'duration_change':\n      return newIsYearly.value\n        ? bodies.durationChangeBody\n        : bodies.durationChangeBodyMonthly\n    default:\n      return ''\n  }\n})\nconst bannerSegments = computed(() =>\n  splitPlaceholders(bannerBody.value, [\n    'plan',\n    'date',\n    'newPlan',\n    'nextDate',\n    'amount'\n  ] as const).map((segment) => {\n    if (segment.kind === 'text') return { text: segment.text, emphasis: false }\n    if (segment.key === 'amount') {\n      return { text: chargeDisplay.value, emphasis: true }\n    }\n    return { text: bannerValues.value[segment.key], emphasis: false }\n  })\n)\n\nconst newMonthlyUsd = computed(() => {\n  const cents = previewData.new_plan.price_cents\n  return (newIsYearly.value ? cents / 12 : cents) / 100\n})\nconst heroPrice = computed(() => newMonthlyUsd.value.toFixed(0))\n\nconst annualTotalFormatted = computed(\n  () => `$${formatNumber(previewData.new_plan.price_cents / 100, locale)}`\n)\n\nconst refillCredits = computed(() =>\n  formatNumber(\n    newIsYearly.value ? plan.monthlyCredits * 12 : plan.monthlyCredits,\n    locale\n  )\n)\nconst refillLabel = computed(() => {\n  if (isImmediate.value) {\n    return newIsYearly.value\n      ? copy.creditsYoullGetToday\n      : copy.eachMonthCreditsRefill\n  }\n  return newIsYearly.value\n    ? copy.eachYearCreditsRefill\n    : copy.creditsRefillMonthlyTo\n})\n\nconst billedLabel = computed(() =>\n  newIsYearly.value\n    ? copy.billedYearly(annualTotalFormatted.value)\n    : copy.billedMonthly\n)\n\nconst planDetails = computed(() =>\n  isImmediate.value\n    ? [billedLabel.value, copy.switchesToday]\n    : [copy.startsOn(effectiveDateLabel.value)]\n)\n\nconst refillNote = computed(() => {\n  if (isImmediate.value) return newIsYearly.value ? copy.refillReplacesNote : ''\n  return newIsYearly.value\n    ? copy.billedYearly(annualTotalFormatted.value)\n    : copy.billedEachMonth(`$${formatNumber(newMonthlyUsd.value, locale)}`)\n})\n\nconst discounts = computed(() =>\n  isImmediate.value\n    ? (previewData.discounts ?? []).map((discount) => ({\n        key: `${discount.kind}:${discount.code}`,\n        label: copy.discount[discount.kind],\n        name: discount.name || discount.code,\n        amount: discount.amount_off_cents\n          ? `$${formatUsdFromCents(discount.amount_off_cents)}`\n          : ''\n      }))\n    : []\n)\n\nconst effectiveDateLabel = computed(() => formatDate(previewData.effective_at))\n// The server's renewal date, the one the summary's renewal line shows. With\n// none, the notice leaves the renewal clause out rather than guess one.\nconst nextPaymentDate = computed(() => {\n  const renewsAt = resolveRenewalDate(previewData)\n  return renewsAt ? formatDate(renewsAt) : undefined\n})\n\nconst bannerValues = computed(() => ({\n  plan: currentPlanName,\n  date: cancelAt.value ? formatDate(cancelAt.value) : '',\n  newPlan: plan.name,\n  nextDate: nextPaymentDate.value ?? ''\n}))\n\nconst confirmTitle = computed(() =>\n  isImmediate.value ? copy.confirmUpgradeTitle : copy.confirmChangeTitle\n)\nconst confirmCta = computed(() => {\n  // Gated on isReactivating, like the banner and the emitted consent, so the\n  // label never promises a reactivation the click will not confirm.\n  if (!isReactivating.value) {\n    return isImmediate.value ? copy.confirmUpgradeCta : copy.confirmChange\n  }\n  if (reactivationVariant.value === 'downgrade') {\n    return copy.reactivation.confirmButton\n  }\n  return copy.reactivation.confirmButtonWithCharge(chargeDisplay.value)\n})\nconst amountDueToday = computed(\n  () => formatAmountDueToday(previewData, locale) || copy.quoteUnavailable\n)\nconst renewalTerms = computed(() => {\n  const amount = formatRenewalAmount(previewData, locale)\n  if (!amount) return copy.quoteUnavailable\n  const renewsAt = resolveRenewalDate(previewData)\n  if (!renewsAt) return copy.renewsAtAmount(amount)\n  return copy.renewsAt(amount, formatDate(renewsAt))\n})\n</script>\n","export interface CreditStop {\n  /** Backend stop identifier (e.g. \"team_700\"), sent on subscribe. Present for\n   *  API-sourced stops; absent only for the hardcoded OSS / pre-deploy fallback. */\n  id?: string\n  /** Monthly subscription price in USD (pre-discount). */\n  usd: number\n  /** Monthly credit grant at this stop. */\n  credits: number\n  /**\n   * Yearly-commitment discount applied to `usd`, as a whole-number percent.\n   * Threshold-based per the pricing decision (Slack — Alex Tov, 2026-05-08):\n   * yearly tiers are 0 / 5 / 10 / 15 / 20% with nothing in between.\n   * Monthly halves these (0 / 2.5 / 5 / 7.5 / 10%) — confirmed in PRD: GA Team\n   * Billing (\"for monthly the discount is halved\"). `CreditSlider` derives the\n   * monthly value from this field via its `cycle` prop, so only the yearly\n   * tiers are stored here.\n   */\n  discountPercentYearly: number\n}\n\n/** A selected slider stop, as emitted by the pricing table's team column. */\nexport interface TeamPlanSelection {\n  /** Backend stop identifier (e.g. \"team_700\"), sent on subscribe. Present for\n   *  API-sourced stops; absent only for the hardcoded OSS / pre-deploy fallback. */\n  id?: string\n  /** Pre-discount monthly price in USD (the struck-through list price). */\n  usd: number\n  /** Monthly credit grant at this stop. */\n  credits: number\n  /** Cycle-adjusted discounted monthly price in USD — what the user actually pays. */\n  discountedUsd: number\n}\n\n/**\n * Team-plan credit-subscription slider stops — OSS / pre-deploy fallback.\n *\n * The live set comes from `GET /api/billing/plans → team_credit_stops` (mapped\n * via `mapApiTeamCreditStops`); these hardcoded DES-197 breakpoints render only\n * when the API doesn't supply them. The slider snaps to exactly these 5 fixed\n * breakpoints — the user cannot select a value in between. The `credits` figures\n * equal `usdToCredits(usd)` at the current rate (`CREDITS_PER_USD = 211`); a unit\n * test guards against rate drift silently changing the designed values.\n */\nexport const TEAM_PLAN_CREDIT_STOPS: readonly CreditStop[] = [\n  { usd: 200, credits: 42_200, discountPercentYearly: 0 },\n  { usd: 400, credits: 84_400, discountPercentYearly: 5 },\n  { usd: 700, credits: 147_700, discountPercentYearly: 10 },\n  { usd: 1_400, credits: 295_400, discountPercentYearly: 15 },\n  { usd: 2_500, credits: 527_500, discountPercentYearly: 20 }\n] as const\n\n/** Default stop per DES-197: index 2 = $700 / 147,700 credits. */\nexport const DEFAULT_TEAM_PLAN_STOP_INDEX = 2\n\n/**\n * Per-credit Team plan slug for a billing cadence (cloud catalog). The slug\n * encodes the cadence; `POST /api/billing/subscribe` reads `plan_slug` +\n * `team_credit_stop_id` and resolves all amounts server-side from the stop.\n */\nexport function getTeamPlanSlug(billingCycle: 'monthly' | 'yearly'): string {\n  return billingCycle === 'yearly'\n    ? 'team_per_credit_annual'\n    : 'team_per_credit_monthly'\n}\n","import type {\n  SubscriptionCheckoutTier,\n  SubscriptionCheckoutType\n} from '@comfyorg/account-core/billing'\n\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport { useAuthStore } from '@/stores/authStore'\n\ninterface TrackWorkspaceCheckoutStartedOptions {\n  tier: SubscriptionCheckoutTier\n  cycle: BillingCycle\n  checkoutType: SubscriptionCheckoutType\n  billingOpId: string\n  paymentIntentSource?: PaymentIntentSource\n}\n\nexport function trackWorkspaceCheckoutStarted({\n  tier,\n  cycle,\n  checkoutType,\n  billingOpId,\n  paymentIntentSource\n}: TrackWorkspaceCheckoutStartedOptions) {\n  const { userId } = useAuthStore()\n  if (!userId) return\n\n  useTelemetry()?.trackBeginCheckout({\n    user_id: userId,\n    tier,\n    cycle,\n    checkout_type: checkoutType,\n    billing_op_id: billingOpId,\n    ...(paymentIntentSource\n      ? { payment_intent_source: paymentIntentSource }\n      : {})\n  })\n}\n","import type {\n  BillingClient,\n  CheckoutEntryFlow,\n  SubscriptionCheckoutType\n} from '@comfyorg/account-core/billing'\nimport { computed, onScopeDispose, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { ToastId } from '@/types/toastId'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport type { CheckoutTierKey } from '@/composables/billing/types'\nimport { getComfyPlatformBaseUrl } from '@/config/comfyApi'\nimport { paymentReturnUrl } from '@/platform/cloud/subscription/utils/paymentReturnUrl'\nimport { amountDueTodayChanged } from '@comfyorg/account-ui/billing/checkout'\nimport { getTeamPlanSlug } from '@/platform/cloud/subscription/constants/teamPlanCreditStops'\nimport type { TeamPlanSelection } from '@/platform/cloud/subscription/constants/teamPlanCreditStops'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { categorizeBillingApiError } from '@/platform/telemetry/utils/billingFailureCategory'\nimport { createBillingPortalReporter } from '@/platform/telemetry/utils/billingPortalTelemetry'\nimport { api } from '@/scripts/api'\nimport { useAuthStore } from '@/stores/authStore'\nimport { getErrorMessage } from '@/utils/errorUtil'\nimport type {\n  Plan,\n  PreviewSubscribeOptions,\n  PreviewSubscribeResponse,\n  SavedPaymentMethod,\n  SubscribeOptions\n} from '@/platform/workspace/api/workspaceApi'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport { openHostedBillingTab } from '@/platform/workspace/billing/openHostedBillingTab'\nimport { registerRefreshOnReturn } from '@/platform/workspace/billing/refreshOnReturn'\nimport type { SettledSubscribeResponse } from '@/platform/workspace/billing/sdk/subscriptionOperationView'\nimport {\n  SettledOperationError,\n  billingClientOf\n} from '@/platform/workspace/billing/sdk/subscriptionOperationView'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useSubscriptionRail } from '@/platform/workspace/composables/useSubscriptionRail'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { useBillingOperationStore } from '@/platform/workspace/stores/billingOperationStore'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport {\n  bindOperationToCheckoutJourney,\n  getActiveCheckoutJourney,\n  resolveCheckoutAssignment,\n  resolveCheckoutJourney,\n  resolveEntrySource\n} from '@/platform/workspace/utils/checkoutJourney'\nimport type { CheckoutJourneyRecord } from '@/platform/workspace/utils/checkoutJourney'\nimport {\n  handOffCheckoutJourney,\n  trackCheckoutJourneyPhase,\n  useCheckoutJourneyExit\n} from '@/platform/workspace/utils/checkoutJourneyTelemetry'\nimport {\n  clearPendingSubscriptionCheckoutIfTerminal,\n  savePendingSubscriptionCheckout\n} from '@/platform/workspace/utils/pendingSubscriptionCheckout'\nimport { trackWorkspaceCheckoutStarted } from '@/platform/workspace/utils/workspaceCheckoutTelemetry'\nimport { openBillingUrl } from '@/platform/workspace/billing/billingTab'\n\ntype CheckoutStep = 'pricing' | 'preview' | 'success'\ninterface SelectedTeamCheckout {\n  stop: TeamPlanSelection\n  checkoutType: SubscriptionCheckoutType\n}\n\ninterface SubscriptionCheckoutOptions {\n  tierPlanType?: 'personal' | 'team'\n  embeddedCheckoutEnabled?: boolean\n}\n\ntype SubscriptionPaymentOptions = Pick<\n  SubscribeOptions,\n  | 'confirmationToken'\n  | 'promotionCode'\n  | 'quoteId'\n  | 'quoteVersion'\n  | 'savedPaymentMethodId'\n>\n\n/**\n * Which screen the `preview` step shows. Only a change prorates: a team change\n * carries `previewData`, a personal change is anything other than `new_subscription`;\n * the rest are display-only fresh-subscribe confirms.\n */\ntype PreviewVariant =\n  | 'team-change'\n  | 'team-new'\n  | 'personal-change'\n  | 'personal-new'\n  | null\n\nconst BILLING_PORTAL_ORIGINS = new Set([\n  'https://billing.stripe.com',\n  'https://checkout.comfy.org'\n])\n\nfunction parseBillingPortalUrl(url: unknown): URL | null {\n  if (typeof url !== 'string') return null\n  try {\n    const portalUrl = new URL(url)\n    return BILLING_PORTAL_ORIGINS.has(portalUrl.origin) ? portalUrl : null\n  } catch {\n    return null\n  }\n}\n\n// Module-scoped so closing checkout while Stripe is open doesn't drop the return refresh.\nlet stopPaymentRecoveryReturnRefresh: (() => void) | null = null\n\nfunction armPaymentRecoveryReturnRefresh(): void {\n  stopPaymentRecoveryReturnRefresh?.()\n  const { fetchStatus } = useBillingContext()\n  stopPaymentRecoveryReturnRefresh = registerRefreshOnReturn(fetchStatus)\n}\n\n/** Thrown by `assertReactivationAmountUnchanged` when a fresh preview no\n *  longer matches the billing state the reactivation banner showed and the\n *  user consented to. Caught by the surrounding try/catch and surfaced\n *  through the same toast as any other subscribe failure. */\nclass ReactivationAmountChangedError extends Error {}\n\nexport function findPlanSlug(\n  plans: Plan[],\n  tierKey: CheckoutTierKey,\n  billingCycle: BillingCycle\n): string | null {\n  const apiDuration = billingCycle === 'yearly' ? 'ANNUAL' : 'MONTHLY'\n  const apiTier = tierKey.toUpperCase()\n  const plan = plans.find(\n    (p) => p.tier === apiTier && p.duration === apiDuration\n  )\n  return plan?.slug ?? null\n}\n\nexport function useSubscriptionCheckout(\n  emit: {\n    (e: 'close', subscribed: boolean): void\n  },\n  paymentIntentSource?: PaymentIntentSource,\n  {\n    tierPlanType = 'personal',\n    embeddedCheckoutEnabled = false\n  }: SubscriptionCheckoutOptions = {}\n) {\n  const { t } = useI18n()\n  const toast = useToast()\n  const {\n    subscribe,\n    previewSubscribe,\n    plans,\n    fetchPlans,\n    fetchStatus,\n    isTeamPlan,\n    resubscribe,\n    subscription\n  } = useBillingContext()\n  const { shouldUseWorkspaceBilling } = useBillingRouting()\n  const { canSubscribeSelfServe, canChangeSeats, canDowngradeToPersonal } =\n    useBillingCapabilities()\n  const { permissions, canReactivatePlan } = useWorkspaceUI()\n  const telemetry = useTelemetry()\n  const billingOperationStore = useBillingOperationStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const subscriptionRail = useSubscriptionRail()\n\n  const checkoutStep = ref<CheckoutStep>('pricing')\n  const isLoadingPreview = ref(false)\n  const loadingTier = ref<CheckoutTierKey | null>(null)\n  const isSubscribing = ref(false)\n  const isApplyingPromotionCode = ref(false)\n  const isResubscribing = ref(false)\n  const previewData = ref<PreviewSubscribeResponse | null>(null)\n  const quoteIsCurrent = ref(false)\n  const savedPaymentMethods = ref<SavedPaymentMethod[]>([])\n  const selectedSavedPaymentMethodId = ref<string | null>(null)\n  const selectedTierKey = ref<CheckoutTierKey | null>(null)\n  const selectedTeamCheckout = ref<SelectedTeamCheckout | null>(null)\n  let teamPreviewRequestId = 0\n  let promotionPreviewRequestId = 0\n  let checkoutMutationOwner = 0\n  let checkoutMutationSeq = 0\n  let activeCheckoutAttemptStartedAt: number | undefined\n  let lastEmittedPreviewRevision: string | undefined\n  const paymentRecoveryToasts: ToastId[] = []\n  function dismissToasts(ids: ToastId[]) {\n    for (const id of ids.splice(0)) toast.dismiss(id)\n  }\n  onScopeDispose(() => dismissToasts(paymentRecoveryToasts))\n  useCheckoutJourneyExit()\n  // Some legacy-rail status reads cannot expose a scheduled cancellation even\n  // though the subscribe authority can see it in Stripe. Once that authority\n  // rejects an unconfirmed change, keep the consent screen in reactivation\n  // mode until the user backs out or completes the change.\n  const reactivationRequired = ref(false)\n  const selectedBillingCycle = ref<BillingCycle>('yearly')\n  const activeCheckoutOperationId = ref<string | null>(null)\n  // The operation this checkout is watching, from whichever rail is driving it.\n  // On the subscription rail the lifecycle owns it, so reading only the legacy\n  // store left the parked-recovery prompt, the authentication state and the\n  // busy state all answering off a store nothing was writing.\n  //\n  // Both are consulted, rail first, because the rail owning the flag does not\n  // mean it owns every operation: a subscribe that fell back to the legacy\n  // transport on a 404 registers its poller in the legacy store while the flag\n  // is still on, and reading only the rail would lose that one entirely.\n  const activeCheckoutOperation = computed(() => {\n    const operationId = activeCheckoutOperationId.value\n    if (!operationId) {\n      return (\n        subscriptionRail?.subscriptionActionOperation ??\n        billingOperationStore.subscriptionActionOperation\n      )\n    }\n    const operation =\n      subscriptionRail?.getOperation(operationId) ??\n      billingOperationStore.getOperation(operationId)\n    return operation?.workspaceId === workspaceStore.activeWorkspaceId\n      ? operation\n      : undefined\n  })\n  const activeCheckoutActionUrl = computed(\n    () =>\n      activeCheckoutOperation.value?.actionUrl ??\n      subscriptionRail?.subscriptionActionUrl ??\n      null\n  )\n  // The server says whether the operation is parked; the client no longer\n  // guesses. Only awaiting_payment_method offers this recovery — an operation\n  // parked on an invoice needs authentication, which actionUrl already drives.\n  // A null phase is no claim, so the poll simply continues.\n  const parkedCheckoutRecovery = computed(\n    () => activeCheckoutOperation.value?.phase === 'awaiting_payment_method'\n  )\n  const authenticationState = computed(\n    () => activeCheckoutOperation.value?.authenticationState ?? null\n  )\n  const authenticationError = computed(\n    () => activeCheckoutOperation.value?.errorMessage ?? null\n  )\n  const reconciliationOperationId = computed(() =>\n    activeCheckoutOperation.value?.status === 'reconciliation_needed'\n      ? activeCheckoutOperation.value.opId\n      : null\n  )\n  // Busy from submit until the checkout presents a terminal step. A pending\n  // operation only releases the confirm action while it is parked on the\n  // customer (a challenge to complete, a failed attempt to retry, a checkout\n  // still awaiting a card); the in-page challenge this tab drives keeps it\n  // busy, and a succeeded operation stays busy for the beat between settlement\n  // and the success step taking over — that beat reopened the pay button\n  // mid-checkout. A parked checkout keeps polling either way: releasing the\n  // action is about who is being waited on, not whether we are still watching.\n  const isPolling = computed(() => {\n    const operation = activeCheckoutOperation.value\n    if (!operation) return false\n    if (operation.status === 'succeeded') return true\n    if (operation.status !== 'pending') return false\n    if (operation.isAuthenticating) return true\n    // Deliberately narrower than isBlockedOnCustomerPhase: releasing the action\n    // exists so the customer can supply the card this park is waiting for. An\n    // invoice park has no such re-submit route — the server refuses a second\n    // operation while this one is open — so it keeps the action busy.\n    if (operation.phase === 'awaiting_payment_method') return false\n    return (\n      operation.authenticationState !== 'failed_retryable' &&\n      operation.authenticationState !== 'requires_action'\n    )\n  })\n  // Only the SDK rail carries the server's `cancelable` and the command that\n  // acts on it. A successful cancel wakes the lifecycle, whose re-read settles\n  // the operation through the existing failed path.\n  const cancelablePaymentId = computed(() => {\n    const opId = activeCheckoutOperation.value?.opId\n    return opId && subscriptionRail?.getOperation(opId)?.cancelable\n      ? opId\n      : null\n  })\n  const paymentCancelable = computed(() => cancelablePaymentId.value !== null)\n  const isCancelingPayment = ref(false)\n  const cancelPaymentError = ref<string | null>(null)\n\n  async function cancelPayment() {\n    const opId = cancelablePaymentId.value\n    if (!opId || !subscriptionRail || isCancelingPayment.value) return\n    isCancelingPayment.value = true\n    cancelPaymentError.value = null\n    const outcome = await subscriptionRail.cancelOperation(opId)\n    isCancelingPayment.value = false\n    if (outcome.status === 'error')\n      cancelPaymentError.value = outcome.error.message\n    else if (outcome.status === 'unavailable')\n      cancelPaymentError.value = t('billingOperation.cancelPaymentFailed')\n  }\n\n  // The lock is owned by one attempt at a time. An attempt that releases early\n  // (see advanceToSuccessOnOperation) still runs its own finally afterwards, by\n  // which point a newer attempt may hold the lock — releasing on a bare boolean\n  // there would hand a third attempt a lock it does not own and let two submits\n  // run concurrently. So a release only counts from the holder.\n  function beginCheckoutMutation(): number {\n    if (checkoutMutationOwner !== 0) return 0\n    checkoutMutationOwner = ++checkoutMutationSeq\n    return checkoutMutationOwner\n  }\n\n  function finishCheckoutMutation(token: number) {\n    if (token !== 0 && checkoutMutationOwner === token)\n      checkoutMutationOwner = 0\n  }\n  const selectedTeamStop = computed(\n    () => selectedTeamCheckout.value?.stop ?? null\n  )\n  const isTeamCheckout = computed(() => selectedTeamCheckout.value !== null)\n  function isSubscriptionCancelled(): boolean {\n    return subscription.value?.isCancelled ?? false\n  }\n\n  // An absent `requires_reactivation_confirmation` means the server did not\n  // decide, so fall back to the subscription's own state rather than assuming\n  // a cancellation the user may never have had.\n  function previewRequiresReactivation(\n    preview: PreviewSubscribeResponse | null | undefined\n  ): boolean {\n    return (\n      preview?.requires_reactivation_confirmation ?? isSubscriptionCancelled()\n    )\n  }\n\n  function hasQuoteIdentity(\n    preview: PreviewSubscribeResponse\n  ): preview is PreviewSubscribeResponse & {\n    quote_id: string\n    quote_version: number\n  } {\n    return Boolean(preview.quote_id) && preview.quote_version !== undefined\n  }\n\n  function installPreview(preview: PreviewSubscribeResponse): boolean {\n    if (!preview.allowed) return false\n    previewData.value = preview\n    if (embeddedCheckoutEnabled) {\n      reactivationRequired.value = previewRequiresReactivation(preview)\n    }\n    quoteIsCurrent.value = true\n\n    const journey = getActiveCheckoutJourney()\n    if (journey) {\n      const revision = hasQuoteIdentity(preview)\n        ? `${preview.quote_id}:${preview.quote_version}`\n        : undefined\n      // Once per accepted revision: a re-render or refresh that reinstalls the\n      // same quote must not emit another preview_ready.\n      if (revision === undefined || revision !== lastEmittedPreviewRevision) {\n        lastEmittedPreviewRevision = revision\n        trackCheckoutJourneyPhase(journey, {\n          phase: 'preview_ready',\n          ...(revision !== undefined && { preview_revision: revision })\n        })\n      }\n    }\n    return true\n  }\n\n  function requiresReactivationConfirmation(): boolean {\n    if (embeddedCheckoutEnabled) {\n      return previewRequiresReactivation(previewData.value)\n    }\n    return isSubscriptionCancelled() || reactivationRequired.value\n  }\n\n  // The transition workflows charge the subscription's existing default\n  // method and reject a payment-method selection outright, so only an\n  // initial-style checkout may carry the auto-selected saved method.\n  function subscribeAcceptsSavedMethod(): boolean {\n    return (\n      !previewData.value ||\n      previewData.value.transition_type === 'new_subscription'\n    )\n  }\n\n  function buildPaymentOptions(\n    quote: PreviewSubscribeResponse | null,\n    confirmationToken?: string,\n    promotionCode?: string\n  ): SubscriptionPaymentOptions {\n    return {\n      ...(confirmationToken && { confirmationToken }),\n      ...(!confirmationToken &&\n        subscribeAcceptsSavedMethod() &&\n        selectedSavedPaymentMethodId.value && {\n          savedPaymentMethodId: selectedSavedPaymentMethodId.value\n        }),\n      promotionCode: quote?.promotion_code ?? promotionCode,\n      ...(quote &&\n        hasQuoteIdentity(quote) && {\n          quoteId: quote.quote_id,\n          quoteVersion: quote.quote_version\n        })\n    }\n  }\n\n  async function loadSavedPaymentMethods(): Promise<void> {\n    if (!embeddedCheckoutEnabled || !shouldUseWorkspaceBilling.value) return\n    try {\n      const rail = useBillingReadRail()\n      const methods =\n        rail === null\n          ? await workspaceApi.listSavedPaymentMethods()\n          : await readOnRail(rail.readPaymentMethods, 'listSavedPaymentMethods')\n      if (methods === undefined) return\n      savedPaymentMethods.value = methods\n      selectedSavedPaymentMethodId.value =\n        methods.find((method) => method.is_default)?.id ?? null\n    } catch {\n      savedPaymentMethods.value = []\n      selectedSavedPaymentMethodId.value = null\n    }\n  }\n\n  function invalidateQuote(): void {\n    quoteIsCurrent.value = false\n  }\n\n  function withCurrentPromotion(\n    options: PreviewSubscribeOptions = {}\n  ): PreviewSubscribeOptions {\n    const promotionCode = previewData.value?.promotion_code\n    return {\n      ...options,\n      ...(promotionCode && { promotionCode })\n    }\n  }\n\n  // A cancelled subscription needs confirm_reactivation, and the only place\n  // that can honestly collect it is the reactivation banner. Paths with no\n  // banner (add-payment preview, a preview-less team-new fallback) always\n  // call in with confirmReactivation=false, so block here instead of sending\n  // a request the BE is guaranteed to reject with no way for the user to\n  // consent.\n  function notifyReactivationConfirmationRequired(): void {\n    toast.error(t('g.error'), {\n      description: t('subscription.preview.reactivation.confirmationRequired')\n    })\n  }\n\n  function isExistingPlanPreview(\n    preview: PreviewSubscribeResponse | null | undefined\n  ): preview is PreviewSubscribeResponse & { allowed: true } {\n    return !!preview?.allowed && preview.transition_type !== 'new_subscription'\n  }\n\n  function isReactivationCapablePreview(\n    preview: PreviewSubscribeResponse | null | undefined\n  ): preview is PreviewSubscribeResponse & { allowed: true } {\n    return (\n      isExistingPlanPreview(preview) &&\n      !!preview.current_plan &&\n      !!(subscription.value?.endDate ?? preview.current_plan.period_end)\n    )\n  }\n\n  function isUsableTeamPreview(\n    preview: PreviewSubscribeResponse | null | undefined,\n    checkoutType: SubscriptionCheckoutType\n  ): preview is PreviewSubscribeResponse & { allowed: true } {\n    if (isSubscriptionCancelled()) return isReactivationCapablePreview(preview)\n    return checkoutType === 'change'\n      ? isExistingPlanPreview(preview)\n      : Boolean(preview?.allowed)\n  }\n\n  function reactivationMaterialSnapshot(\n    preview: PreviewSubscribeResponse,\n    ignoreTimeDerivedTodayValues = false\n  ): string {\n    type RuntimePlan = Omit<\n      NonNullable<PreviewSubscribeResponse['new_plan']>,\n      'seat_summary'\n    > & {\n      seat_summary?: PreviewSubscribeResponse['new_plan']['seat_summary']\n    }\n\n    const planSnapshot = (plan: RuntimePlan | undefined) => {\n      if (!plan) return null\n      const { seat_summary: seatSummary } = plan\n      return [\n        plan.slug,\n        plan.tier,\n        plan.duration,\n        plan.price_cents,\n        plan.credits_cents,\n        seatSummary?.seat_count,\n        seatSummary?.total_cost_cents,\n        seatSummary?.total_credits_cents,\n        plan.period_start,\n        plan.period_end\n      ]\n    }\n\n    return JSON.stringify([\n      preview.allowed,\n      preview.transition_type,\n      preview.is_immediate,\n      preview.is_immediate ? null : preview.effective_at,\n      preview.cost_next_period_cents,\n      ignoreTimeDerivedTodayValues ? null : preview.credits_today_cents,\n      preview.credits_next_period_cents,\n      planSnapshot(preview.current_plan),\n      planSnapshot(preview.new_plan)\n    ])\n  }\n\n  // Current backends return the exact proration instant used for the preview;\n  // subscribe() echoes it back so the charge cannot drift while the consent\n  // screen is open. A fresh preview still checks non-time-based plan, quantity,\n  // credit, and period state before the charge is submitted.\n  async function assertReactivationAmountUnchanged(\n    planSlug: string,\n    options?: PreviewSubscribeOptions\n  ): Promise<void> {\n    const confirmedPreview = previewData.value\n    const freshPreview = await previewSubscribe(\n      planSlug,\n      withCurrentPromotion(options)\n    )\n    if (!freshPreview?.allowed) {\n      throw new Error(freshPreview?.reason || t('subscription.subscribeFailed'))\n    }\n\n    if (confirmedPreview?.proration_at) {\n      const isImmediateTransition = confirmedPreview.is_immediate\n      const amountChanged = isImmediateTransition\n        ? freshPreview.cost_today_cents > confirmedPreview.cost_today_cents\n        : freshPreview.cost_today_cents !== confirmedPreview.cost_today_cents\n      const materialChanged =\n        reactivationMaterialSnapshot(freshPreview, isImmediateTransition) !==\n        reactivationMaterialSnapshot(confirmedPreview, isImmediateTransition)\n      if (amountChanged || materialChanged) {\n        installPreview(freshPreview)\n        throw new ReactivationAmountChangedError(\n          t(\n            amountChanged\n              ? 'subscription.preview.reactivation.amountChanged'\n              : 'subscription.preview.reactivation.confirmationRequired'\n          )\n        )\n      }\n      return\n    }\n\n    const amountChanged =\n      freshPreview.cost_today_cents !==\n      (confirmedPreview?.cost_today_cents ?? 0)\n    const materialChanged =\n      !!confirmedPreview &&\n      reactivationMaterialSnapshot(freshPreview) !==\n        reactivationMaterialSnapshot(confirmedPreview)\n    // Install regardless of outcome: on drift this is what makes the confirm\n    // screen show the new amount and resets prior consent (via the\n    // component's own preview watcher), so the next attempt compares\n    // against what's on screen instead of repeating this same failure.\n    installPreview(freshPreview)\n    if (amountChanged || materialChanged) {\n      throw new ReactivationAmountChangedError(\n        t(\n          amountChanged\n            ? 'subscription.preview.reactivation.amountChanged'\n            : 'subscription.preview.reactivation.confirmationRequired'\n        )\n      )\n    }\n  }\n\n  function hasErrorCode(error: unknown, code: string): boolean {\n    return (\n      typeof error === 'object' &&\n      error !== null &&\n      'code' in error &&\n      error.code === code\n    )\n  }\n\n  /**\n   * The portal URL for recovery, from whichever rail owns the subscription.\n   * An `unavailable` route is not deployed here, so the legacy client answers;\n   * a failure throws into the caller's catch, where a legacy throw already\n   * lands.\n   */\n  async function readPaymentPortalUrl(\n    returnUrl: string\n  ): Promise<{ url: string; billingClient: BillingClient }> {\n    if (subscriptionRail) {\n      const outcome = await subscriptionRail.openPaymentPortal(returnUrl)\n      if (outcome.status === 'ok') {\n        return { url: outcome.value, billingClient: 'sdk' }\n      }\n      if (outcome.status === 'error') throw outcome.error\n    }\n    const { url } = await workspaceApi.getPaymentPortalUrl(returnUrl)\n    return { url, billingClient: 'legacy' }\n  }\n\n  async function recoverOutstandingPayment(\n    error: unknown,\n    isCurrent: () => boolean = () => true\n  ) {\n    const readRail = useBillingReadRail()\n    const hasPaymentRecoveryCode =\n      hasErrorCode(error, 'SUBSCRIPTION_PAYMENT_REQUIRED') ||\n      hasErrorCode(error, 'OUTSTANDING_PAYMENT_REQUIRED')\n    let requiresRecovery = hasPaymentRecoveryCode\n    if (!requiresRecovery && hasErrorCode(error, 'TRANSITION_NOT_ALLOWED')) {\n      try {\n        const status =\n          readRail === null\n            ? await workspaceApi.getBillingStatus()\n            : await readOnRail(readRail.readStatus, 'getBillingStatus')\n        requiresRecovery =\n          status?.billing_status === 'payment_failed' ||\n          status?.billing_status === 'paused'\n      } catch {\n        return null\n      }\n    }\n    if (!requiresRecovery || !isCurrent()) return null\n\n    const portal = createBillingPortalReporter(telemetry, 'payment_recovery')\n    let billingClient: BillingClient | undefined\n    try {\n      const returnUrl = `${globalThis.location.origin}${globalThis.location.pathname}`\n      const portalResponse = await readPaymentPortalUrl(returnUrl)\n      billingClient = portalResponse.billingClient\n      const portalUrl = parseBillingPortalUrl(portalResponse.url)\n      if (!isCurrent()) return null\n      if (!portalUrl) {\n        throw new Error(\n          t('toastMessages.failedToAccessBillingPortal', {\n            error: t('toastMessages.invalidBillingPortalUrl')\n          })\n        )\n      }\n      if (!openBillingUrl(portalUrl.href)) {\n        portal.blocked(billingClient)\n        // The open above ran after an await, so it had no user gesture behind\n        // it and got blocked. The toast's own button click is a gesture, so\n        // retrying from there isn't blocked.\n        paymentRecoveryToasts.push(\n          toast.warning(t('g.warning'), {\n            description: t('subscription.preview.paymentPopupBlocked'),\n            action: {\n              label: t('subscription.planLoadErrorRetry'),\n              // The toast can outlive this attempt (a newer one started, or the\n              // checkout reset); a stale click must not reopen its captured URL.\n              onClick: () => {\n                if (!isCurrent()) return\n                if (openBillingUrl(portalUrl.href)) {\n                  portal.opened(billingClient)\n                } else {\n                  portal.blocked(billingClient)\n                }\n                armPaymentRecoveryReturnRefresh()\n              }\n            }\n          })\n        )\n        return 'blocked'\n      }\n      portal.opened(billingClient)\n      armPaymentRecoveryReturnRefresh()\n      return 'opened'\n    } catch (portalError) {\n      if (!isCurrent()) return null\n      portal.failed(portalError, billingClient)\n      reportError(portalError, {\n        surface: 'workspace',\n        errorType: 'billing_portal_open_failure'\n      })\n      showSubscribeError(hasPaymentRecoveryCode ? error : portalError)\n      return 'failed'\n    }\n  }\n\n  async function refreshExpiredProrationQuote(\n    error: unknown,\n    planSlug: string,\n    options?: PreviewSubscribeOptions\n  ): Promise<boolean> {\n    if (!hasErrorCode(error, 'PRORATION_QUOTE_EXPIRED')) return false\n\n    let freshPreview: PreviewSubscribeResponse | null\n    try {\n      freshPreview = await previewSubscribe(\n        planSlug,\n        withCurrentPromotion(options)\n      )\n    } catch (previewError) {\n      if (!(await recoverOutstandingPayment(previewError))) {\n        showSubscribeError(previewError)\n      }\n      return true\n    }\n    if (!isReactivationCapablePreview(freshPreview)) {\n      resetToPricing()\n      toast.error(t('g.error'), {\n        description: t('subscription.preview.reactivation.unavailable')\n      })\n      return true\n    }\n\n    const amountChanged =\n      !previewData.value ||\n      amountDueTodayChanged(previewData.value, freshPreview)\n    installPreview(freshPreview)\n    toast.error(t('g.error'), {\n      description: t(\n        amountChanged\n          ? 'subscription.preview.reactivation.amountChanged'\n          : 'subscription.preview.reactivation.confirmationRequired'\n      )\n    })\n    return true\n  }\n\n  // Resolves `true` when the checkout stays blocked, `false` when the refresh\n  // cleared the block and the caller may continue.\n  async function refreshPreviewOnReactivationBlock(\n    planSlug: string,\n    options?: PreviewSubscribeOptions\n  ): Promise<boolean> {\n    let freshPreview: PreviewSubscribeResponse | null = null\n    try {\n      freshPreview = await previewSubscribe(\n        planSlug,\n        withCurrentPromotion(options)\n      )\n    } catch (error) {\n      const recovery = await recoverOutstandingPayment(error)\n      if (recovery === 'failed') resetToPricing()\n      if (recovery) return true\n      // Treated the same as an incapable preview below.\n    }\n    if (\n      freshPreview?.requires_reactivation_confirmation !== false &&\n      isReactivationCapablePreview(freshPreview)\n    ) {\n      installPreview(freshPreview)\n      reactivationRequired.value = true\n      notifyReactivationConfirmationRequired()\n      return true\n    }\n    // A first subscription has no prior plan to reactivate, so a valid\n    // new_subscription quote answers the block rather than failing it.\n    if (\n      freshPreview?.allowed &&\n      freshPreview.transition_type === 'new_subscription' &&\n      !isSubscriptionCancelled() &&\n      !previewRequiresReactivation(freshPreview)\n    ) {\n      // No installed quote means no amount the user has already seen; drop the\n      // `!!` and the empty-preview case this branch exists for compares a real\n      // amount against `undefined` and blocks again.\n      const amountChanged =\n        !!previewData.value &&\n        amountDueTodayChanged(previewData.value, freshPreview)\n      installPreview(freshPreview)\n      if (!amountChanged) return false\n      toast.error(t('g.error'), {\n        description: t('subscription.preview.reactivation.amountChanged')\n      })\n      return true\n    }\n    reactivationRequired.value = false\n    resetToPricing()\n    toast.error(t('g.error'), {\n      description: t('subscription.preview.reactivation.unavailable')\n    })\n    return true\n  }\n\n  function canSelectTierPlan(): boolean {\n    return (\n      tierPlanType === 'team' ||\n      !isTeamPlan.value ||\n      (isCloud\n        ? canDowngradeToPersonal.value\n        : permissions.value.canDowngradeToPersonal)\n    )\n  }\n\n  function canPerformCheckout(checkoutType: SubscriptionCheckoutType): boolean {\n    if (!isCloud) return permissions.value.canManageSubscription\n    return checkoutType === 'change'\n      ? canChangeSeats.value\n      : canSubscribeSelfServe.value\n  }\n\n  // Synchronous so the caller can branch before any await: a hosted-tab\n  // open right after this needs the click's transient user activation,\n  // which an await can drop in stricter browsers (Safari).\n  function needsTeamToPersonalDowngrade(): boolean {\n    return tierPlanType !== 'team' && isTeamPlan.value\n  }\n\n  async function showTeamToPersonalDowngrade(\n    planSlug: string,\n    tierKey: CheckoutTierKey\n  ): Promise<void> {\n    const { useBillingDialogs } =\n      await import('@/composables/billing/useBillingDialogs')\n    const result = await useBillingDialogs().showDowngradeToPersonalDialog({\n      planName: t(`subscription.tiers.${tierKey}.name`),\n      planSlug,\n      paymentIntentSource\n    })\n    if (!result) return\n\n    previewData.value = result.preview\n    trackWorkspaceCheckoutStarted({\n      tier: tierKey,\n      cycle: selectedBillingCycle.value,\n      checkoutType: 'change',\n      billingOpId: result.response.billing_op_id,\n      paymentIntentSource\n    })\n    await handleSubscribeResponse(\n      result.response,\n      {\n        tier: tierKey,\n        cycle: selectedBillingCycle.value,\n        checkoutType: 'change'\n      },\n      false\n    )\n  }\n\n  const previewVariant = computed<PreviewVariant>(() => {\n    if (selectedTeamCheckout.value) {\n      return selectedTeamCheckout.value.checkoutType === 'change' ||\n        (previewData.value &&\n          previewData.value.transition_type !== 'new_subscription')\n        ? 'team-change'\n        : 'team-new'\n    }\n    if (previewData.value) {\n      return previewData.value.transition_type === 'new_subscription'\n        ? 'personal-new'\n        : 'personal-change'\n    }\n    return null\n  })\n\n  function getApiPlanSlug(\n    tierKey: CheckoutTierKey,\n    billingCycle: BillingCycle\n  ): string | null {\n    return findPlanSlug(plans.value, tierKey, billingCycle)\n  }\n\n  async function handleSubscribeClick(payload: {\n    tierKey: CheckoutTierKey\n    billingCycle: BillingCycle\n  }) {\n    if (\n      isSubscribing.value ||\n      !canSelectTierPlan() ||\n      (isTeamPlan.value && tierPlanType !== 'team'\n        ? !(isCloud\n            ? canDowngradeToPersonal.value\n            : permissions.value.canDowngradeToPersonal)\n        : isCloud && !canSubscribeSelfServe.value && !canChangeSeats.value)\n    ) {\n      return\n    }\n\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'intent',\n      outcome: 'pending',\n      tier: payload.tierKey,\n      cycle: payload.billingCycle,\n      payment_intent_source: paymentIntentSource\n    })\n    const { tierKey, billingCycle } = payload\n    promotionPreviewRequestId += 1\n\n    reactivationRequired.value = false\n    isLoadingPreview.value = true\n    loadingTier.value = tierKey\n    selectedTierKey.value = tierKey\n    selectedBillingCycle.value = billingCycle\n    const enteredJourney = enterCheckoutJourney(`${tierKey}:${billingCycle}`)\n\n    try {\n      let planSlug = getApiPlanSlug(tierKey, billingCycle)\n      if (!planSlug) {\n        await fetchPlans()\n        planSlug = getApiPlanSlug(tierKey, billingCycle)\n      }\n      if (!planSlug) {\n        toast.error(t('subscription.unableToSubscribe'), {\n          description: t('subscription.planNotAvailable')\n        })\n        return\n      }\n      if (needsTeamToPersonalDowngrade()) {\n        await showTeamToPersonalDowngrade(planSlug, tierKey)\n        return\n      }\n      if (\n        openHostedBillingTab('checkout', {\n          plan: planSlug,\n          source: paymentIntentSource,\n          journeyId: enteredJourney?.journey_id\n        })\n      ) {\n        handOffCheckoutJourney()\n        emit('close', false)\n        return\n      }\n      const response = embeddedCheckoutEnabled\n        ? (\n            await Promise.all([\n              previewSubscribe(planSlug),\n              loadSavedPaymentMethods()\n            ])\n          )[0]\n        : await previewSubscribe(planSlug)\n\n      if (!response || !response.allowed) {\n        const journey = getActiveCheckoutJourney()\n        if (journey) {\n          trackCheckoutJourneyPhase(journey, {\n            phase: 'preview_failed',\n            failure_category: 'unknown'\n          })\n        }\n        toast.error(t('subscription.unableToSubscribe'), {\n          description: response?.reason || t('subscription.planNotAvailable')\n        })\n        return\n      }\n      const checkoutType =\n        response.transition_type === 'new_subscription' ? 'new' : 'change'\n      if (!canPerformCheckout(checkoutType)) return\n\n      installPreview(response)\n      checkoutStep.value = 'preview'\n    } catch (error) {\n      if (await recoverOutstandingPayment(error)) return\n      const journey = getActiveCheckoutJourney()\n      if (journey) {\n        trackCheckoutJourneyPhase(journey, {\n          phase: 'preview_failed',\n          failure_category: categorizeBillingApiError(error)\n        })\n      }\n      toast.error(t('g.error'), {\n        description:\n          getErrorMessage(error) ?? t('subscription.previewLoadFailed')\n      })\n    } finally {\n      isLoadingPreview.value = false\n      loadingTier.value = null\n    }\n  }\n\n  /**\n   * Team-plan checkout entry. A fresh subscribe has nothing to prorate and shows\n   * the display-only \"Confirm your payment\" step. An existing subscriber changing\n   * their credit commitment gets a prorated transition preview when the backend\n   * can describe it; until `preview-subscribe` accepts a team stop the attempt\n   * falls back to the same display-only step.\n   */\n  async function handleSubscribeTeamClick(payload: {\n    stop: TeamPlanSelection\n    billingCycle: BillingCycle\n    isChange?: boolean\n  }) {\n    const checkoutType = payload.isChange ? 'change' : 'new'\n    if (isSubscribing.value || !canPerformCheckout(checkoutType)) return\n\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'intent',\n      outcome: 'pending',\n      tier: 'team',\n      cycle: payload.billingCycle,\n      checkout_type: checkoutType,\n      payment_intent_source: paymentIntentSource\n    })\n    const previewRequestId = ++teamPreviewRequestId\n    promotionPreviewRequestId += 1\n    reactivationRequired.value = false\n    selectedTeamCheckout.value = {\n      stop: payload.stop,\n      checkoutType\n    }\n    selectedBillingCycle.value = payload.billingCycle\n    selectedTierKey.value = null\n    previewData.value = null\n    quoteIsCurrent.value = false\n    const enteredJourney = enterCheckoutJourney(\n      `team:${payload.stop.id}:${payload.billingCycle}`\n    )\n\n    if (\n      payload.stop.id &&\n      openHostedBillingTab('checkout', {\n        plan: getTeamPlanSlug(payload.billingCycle),\n        teamCreditStopId: payload.stop.id,\n        source: paymentIntentSource,\n        journeyId: enteredJourney?.journey_id\n      })\n    ) {\n      handOffCheckoutJourney()\n      emit('close', false)\n      return\n    }\n\n    if (!embeddedCheckoutEnabled) {\n      const teamCreditStopId = payload.stop.id\n      if (!teamCreditStopId) {\n        toast.error(t('subscription.teamPlan.name'), {\n          description: t('subscription.teamPlan.unavailable')\n        })\n        resetToPricing()\n        return\n      }\n      isLoadingPreview.value = true\n\n      let response: PreviewSubscribeResponse | null = null\n      let previewError: unknown\n      try {\n        response = await previewSubscribe(\n          getTeamPlanSlug(payload.billingCycle),\n          { teamCreditStopId }\n        )\n      } catch (error) {\n        previewError = error\n        const recovery = await recoverOutstandingPayment(\n          error,\n          () => previewRequestId === teamPreviewRequestId\n        )\n        if (recovery === 'failed') {\n          resetToPricing()\n          return\n        }\n        if (recovery) return\n      } finally {\n        if (previewRequestId === teamPreviewRequestId) {\n          isLoadingPreview.value = false\n        }\n      }\n\n      if (previewRequestId !== teamPreviewRequestId) return\n      if (isUsableTeamPreview(response, checkoutType)) {\n        installPreview(response)\n        checkoutStep.value = 'preview'\n        return\n      }\n      toast.error(t('subscription.teamPlan.name'), {\n        description:\n          getErrorMessage(previewError) ??\n          (response?.reason || t('subscription.subscribeFailed'))\n      })\n      checkoutStep.value = 'pricing'\n      selectedTeamCheckout.value = null\n      return\n    }\n\n    if (!payload.stop.id) return\n    isLoadingPreview.value = true\n\n    let response: PreviewSubscribeResponse | null = null\n    let previewError: unknown\n    try {\n      const planSlug = getTeamPlanSlug(payload.billingCycle)\n      ;[response] = await Promise.all([\n        previewSubscribe(planSlug, {\n          teamCreditStopId: payload.stop.id\n        }),\n        loadSavedPaymentMethods()\n      ])\n    } catch (error) {\n      previewError = error\n      const recovery = await recoverOutstandingPayment(\n        error,\n        () => previewRequestId === teamPreviewRequestId\n      )\n      if (recovery === 'failed') {\n        resetToPricing()\n        return\n      }\n      if (recovery) return\n    } finally {\n      if (previewRequestId === teamPreviewRequestId) {\n        isLoadingPreview.value = false\n      }\n    }\n\n    if (previewRequestId !== teamPreviewRequestId) return\n\n    if (\n      response?.allowed &&\n      (response.requires_reactivation_confirmation === false ||\n        isReactivationCapablePreview(response))\n    ) {\n      installPreview(response)\n      checkoutStep.value = 'preview'\n      return\n    }\n    toast.error(t('subscription.teamPlan.name'), {\n      description:\n        getErrorMessage(previewError) ??\n        (response?.reason || t('subscription.subscribeFailed'))\n    })\n    checkoutStep.value = 'pricing'\n    selectedTeamCheckout.value = null\n  }\n\n  function resetToPricing() {\n    teamPreviewRequestId += 1\n    promotionPreviewRequestId += 1\n    isLoadingPreview.value = false\n    reactivationRequired.value = false\n    checkoutStep.value = 'pricing'\n    previewData.value = null\n    quoteIsCurrent.value = false\n    selectedTeamCheckout.value = null\n    activeCheckoutOperationId.value = null\n    activeCheckoutAttemptStartedAt = undefined\n    dismissToasts(paymentRecoveryToasts)\n  }\n\n  function handleBackToPricing() {\n    if (isPolling.value || isSubscribing.value) return\n    resetToPricing()\n  }\n\n  function handleSuccessClose() {\n    emit('close', true)\n  }\n\n  async function handleSubscription(\n    confirmReactivation = false,\n    confirmationToken?: string,\n    promotionCode?: string\n  ) {\n    if (!canSelectTierPlan()) return\n    const mutationToken = beginCheckoutMutation()\n    if (!mutationToken) return\n\n    const tierKey = selectedTierKey.value\n    if (!tierKey) {\n      finishCheckoutMutation(mutationToken)\n      return\n    }\n\n    const billingCycle = selectedBillingCycle.value\n    const planSlug = getApiPlanSlug(tierKey, billingCycle)\n    if (!planSlug) {\n      finishCheckoutMutation(mutationToken)\n      return\n    }\n    const checkoutType =\n      previewData.value &&\n      previewData.value.transition_type !== 'new_subscription'\n        ? 'change'\n        : 'new'\n    if (!canPerformCheckout(checkoutType)) {\n      finishCheckoutMutation(mutationToken)\n      return\n    }\n\n    isSubscribing.value = true\n    try {\n      if (needsTeamToPersonalDowngrade()) {\n        await showTeamToPersonalDowngrade(planSlug, tierKey)\n        return\n      }\n      await fetchStatus()\n      if (!confirmReactivation && requiresReactivationConfirmation()) {\n        if (await refreshPreviewOnReactivationBlock(planSlug)) return\n      }\n      const attemptStartedAt = trackSubscriptionStarted({\n        tier: tierKey,\n        cycle: billingCycle,\n        checkoutType\n      })\n      if (confirmReactivation && requiresReactivationConfirmation()) {\n        await assertReactivationAmountUnchanged(planSlug)\n      }\n      const quote = embeddedCheckoutEnabled ? previewData.value : null\n      if (embeddedCheckoutEnabled && quote && !quoteIsCurrent.value) {\n        throw new Error(t('subscription.preview.applyQuoteBeforeContinuing'))\n      }\n      const submittingJourney = getActiveCheckoutJourney()\n      if (submittingJourney) {\n        trackCheckoutJourneyPhase(submittingJourney, { phase: 'submitted' })\n      }\n      const response = await subscribe(planSlug, {\n        ...(embeddedCheckoutEnabled &&\n          buildPaymentOptions(quote, confirmationToken, promotionCode)),\n        returnUrl: embeddedCheckoutEnabled\n          ? paymentReturnUrl()\n          : `${getComfyPlatformBaseUrl()}/payment/success`,\n        cancelUrl: `${getComfyPlatformBaseUrl()}/payment/failed`,\n        confirmReactivation,\n        prorationAt: previewData.value?.is_immediate\n          ? previewData.value.proration_at\n          : undefined,\n        attemptStartedAt\n      })\n\n      if (response) {\n        linkSubmittingJourneyToOperation(\n          submittingJourney,\n          response.billing_op_id\n        )\n        trackWorkspaceCheckoutStarted({\n          tier: tierKey,\n          cycle: billingCycle,\n          checkoutType,\n          billingOpId: response.billing_op_id,\n          paymentIntentSource\n        })\n      }\n      await handleSubscribeResponse(\n        response,\n        {\n          tier: tierKey,\n          cycle: billingCycle,\n          checkoutType,\n          attemptStartedAt\n        },\n        true,\n        mutationToken\n      )\n      activeCheckoutAttemptStartedAt = undefined\n    } catch (error) {\n      if (\n        hasErrorCode(error, 'REACTIVATION_CONFIRMATION_REQUIRED') &&\n        (await refreshPreviewOnReactivationBlock(planSlug))\n      ) {\n        return\n      }\n      trackSubscriptionFailure(\n        {\n          tier: tierKey,\n          cycle: billingCycle,\n          checkoutType,\n          attemptStartedAt: activeCheckoutAttemptStartedAt\n        },\n        error\n      )\n      activeCheckoutAttemptStartedAt = undefined\n      if (await recoverOutstandingPayment(error)) return\n      if (await refreshExpiredProrationQuote(error, planSlug)) return\n      if (embeddedCheckoutEnabled && (await recoverStaleQuote(error))) return\n      showSubscribeError(error)\n    } finally {\n      isSubscribing.value = false\n      finishCheckoutMutation(mutationToken)\n    }\n  }\n\n  // A refused attempt's toast stays until dismissed; a later attempt that\n  // succeeds takes them down rather than leaving a decline over the success.\n  const attemptErrorToasts: ToastId[] = []\n\n  function showSubscribeError(error: unknown) {\n    attemptErrorToasts.push(\n      toast.error(t('g.error'), {\n        description: getErrorMessage(error) ?? t('subscription.subscribeFailed')\n      })\n    )\n  }\n\n  watch(checkoutStep, (step) => {\n    if (step !== 'success') return\n    dismissToasts(attemptErrorToasts)\n  })\n\n  async function recoverStaleQuote(error: unknown): Promise<boolean> {\n    if (!hasErrorCode(error, 'SUBSCRIPTION_QUOTE_STALE')) return false\n    quoteIsCurrent.value = false\n    const refreshed = await applyPromotionCode(\n      previewData.value?.promotion_code ?? '',\n      false,\n      false\n    )\n    if (!refreshed) {\n      resetToPricing()\n      toast.error(t('g.error'), {\n        description: t('subscription.preview.quoteRefreshFailed')\n      })\n      return true\n    }\n    toast.error(t('g.error'), {\n      description: t('subscription.preview.quoteStale')\n    })\n    return true\n  }\n\n  async function applyPromotionCode(\n    promotionCode: string,\n    showFailure = true,\n    lockMutation = true\n  ): Promise<boolean> {\n    if (!embeddedCheckoutEnabled) return false\n    const mutationToken = lockMutation ? beginCheckoutMutation() : 0\n    if (lockMutation && !mutationToken) return false\n    isApplyingPromotionCode.value = true\n    const requestId = ++promotionPreviewRequestId\n    const normalizedInput = promotionCode.trim()\n    let planSlug: string | null\n    let options: PreviewSubscribeOptions\n    if (selectedTeamCheckout.value?.stop.id) {\n      planSlug = getTeamPlanSlug(selectedBillingCycle.value)\n      options = {\n        teamCreditStopId: selectedTeamCheckout.value.stop.id,\n        ...(normalizedInput && { promotionCode: normalizedInput })\n      }\n    } else if (selectedTierKey.value) {\n      planSlug = getApiPlanSlug(\n        selectedTierKey.value,\n        selectedBillingCycle.value\n      )\n      options = normalizedInput ? { promotionCode: normalizedInput } : {}\n    } else {\n      if (lockMutation) finishCheckoutMutation(mutationToken)\n      isApplyingPromotionCode.value = false\n      return false\n    }\n    if (!planSlug) {\n      if (lockMutation) finishCheckoutMutation(mutationToken)\n      isApplyingPromotionCode.value = false\n      return false\n    }\n    quoteIsCurrent.value = false\n    try {\n      const response = await previewSubscribe(planSlug, options)\n      if (!response?.allowed) {\n        throw new Error(response?.reason || t('subscription.subscribeFailed'))\n      }\n      if (requestId !== promotionPreviewRequestId) return false\n      installPreview(response)\n      return true\n    } catch (error) {\n      if (requestId !== promotionPreviewRequestId) return false\n      if (showFailure) showSubscribeError(error)\n      return false\n    } finally {\n      if (requestId === promotionPreviewRequestId) {\n        isApplyingPromotionCode.value = false\n      }\n      if (lockMutation) finishCheckoutMutation(mutationToken)\n    }\n  }\n\n  interface SubscriptionOutcomeContext {\n    tier: CheckoutTierKey | 'team'\n    cycle: BillingCycle\n    checkoutType: SubscriptionCheckoutType\n    /**\n     * Timestamp captured alongside the canonical `subscription_checkout`\n     * `started` event, threaded through to the billing-op poller so its\n     * `duration_ms` spans the full attempt (including the initiating\n     * subscribe call), not just the poll-observation window.\n     */\n    attemptStartedAt?: number\n  }\n\n  function currentSubscriptionEntryFlow(): CheckoutEntryFlow {\n    return subscription.value?.isActive && subscription.value.tier !== 'FREE'\n      ? 'paid_upgrade'\n      : 'initial_subscription'\n  }\n\n  function enterCheckoutJourney(intent: string): CheckoutJourneyRecord | null {\n    const workspaceId = workspaceStore.activeWorkspaceId\n    const ownerUid = useAuthStore().userId\n    if (!workspaceId || !ownerUid) return null\n\n    const entrySource = resolveEntrySource(paymentIntentSource, 'pricing')\n    const resolved = resolveCheckoutJourney({\n      actorUid: ownerUid,\n      workspaceId,\n      entryFlow: currentSubscriptionEntryFlow(),\n      entrySource,\n      paymentIntentSource,\n      // Keyed by source as well as tier/cycle, the way the top-up rail keys by\n      // source alone. Resume matches on actor, workspace, flow and intent but\n      // not source, so without this an abandoned `pricing` preview for a plan\n      // would be resumed by an agent-paywall entry for that same plan and keep\n      // reporting `pricing` for the rest of the journey. A journey already\n      // bound to an operation still wins the slot: a non-match falls through\n      // to the bound-journey check below rather than evicting it.\n      intent: `${entrySource}:${intent}`,\n      uiMode: embeddedCheckoutEnabled ? 'embedded' : 'hosted',\n      assignment: resolveCheckoutAssignment(api.getServerFeatures())\n    })\n    if (resolved.status === 'blocked') return null\n\n    if (!resolved.resumed) {\n      trackCheckoutJourneyPhase(resolved.record, { phase: 'entered' })\n    }\n    return resolved.record\n  }\n\n  function linkSubmittingJourneyToOperation(\n    submittingJourney: CheckoutJourneyRecord | null,\n    billingOpId: string\n  ): void {\n    // Bind only when the submitting journey is still active. A tier/cycle change\n    // mid-request starts a new journey that must not inherit this operation.\n    if (\n      !submittingJourney ||\n      getActiveCheckoutJourney()?.journey_id !== submittingJourney.journey_id\n    ) {\n      return\n    }\n    const linked = bindOperationToCheckoutJourney(billingOpId)\n    if (linked) {\n      trackCheckoutJourneyPhase(linked, {\n        phase: 'operation_linked',\n        billing_op_id: billingOpId\n      })\n    }\n  }\n\n  function trackSubscriptionStarted(\n    context: SubscriptionOutcomeContext\n  ): number | undefined {\n    if (activeCheckoutAttemptStartedAt !== undefined) {\n      return activeCheckoutAttemptStartedAt\n    }\n    if (!shouldUseWorkspaceBilling.value) return undefined\n\n    activeCheckoutAttemptStartedAt = Date.now()\n\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'started',\n      outcome: 'pending',\n      tier: context.tier,\n      cycle: context.cycle,\n      checkout_type: context.checkoutType,\n      payment_intent_source: paymentIntentSource\n    })\n    telemetry?.trackBillingEvent({\n      operation: 'operation',\n      stage: 'started',\n      outcome: 'pending',\n      operation_type: 'subscription',\n      billing_client: billingClientOf(useSubscriptionRail()),\n      tier: context.tier,\n      cycle: context.cycle,\n      checkout_type: context.checkoutType,\n      payment_intent_source: paymentIntentSource\n    })\n    return activeCheckoutAttemptStartedAt\n  }\n\n  function trackSubscriptionFailure(\n    context: SubscriptionOutcomeContext,\n    error?: unknown,\n    errorCode?: 'missing_checkout_response'\n  ) {\n    if (context.attemptStartedAt === undefined) return\n\n    // No checkout_url is a malformed response, not a caught error — 'unknown' is honest here.\n    const failureCategory = errorCode\n      ? 'unknown'\n      : categorizeBillingApiError(error)\n\n    telemetry?.trackBillingEvent({\n      operation: 'subscription_checkout',\n      stage: 'failed',\n      outcome: 'failure',\n      tier: context.tier,\n      cycle: context.cycle,\n      checkout_type: context.checkoutType,\n      payment_intent_source: paymentIntentSource,\n      failure_category: failureCategory,\n      ...(errorCode && { error_code: errorCode }),\n      duration_ms: Date.now() - context.attemptStartedAt\n    })\n    if (error instanceof SettledOperationError) return\n    telemetry?.trackBillingEvent({\n      operation: 'operation',\n      stage: 'failed',\n      outcome: 'failure',\n      operation_type: 'subscription',\n      billing_client: billingClientOf(useSubscriptionRail()),\n      tier: context.tier,\n      cycle: context.cycle,\n      checkout_type: context.checkoutType,\n      payment_intent_source: paymentIntentSource,\n      failure_category: failureCategory,\n      ...(errorCode && { error_code: errorCode }),\n      duration_ms: Date.now() - context.attemptStartedAt\n    })\n  }\n\n  async function handleSubscribeResponse(\n    response: SettledSubscribeResponse | void,\n    context: SubscriptionOutcomeContext,\n    shouldTrackSubscriptionSuccess = true,\n    // 0 when the caller holds no lock; a release from a non-holder is a no-op.\n    mutationToken = 0\n  ): Promise<void> {\n    if (!response) {\n      trackSubscriptionFailure(context, undefined, 'missing_checkout_response')\n      return\n    }\n\n    if (response.status === 'subscribed') {\n      if (\n        shouldTrackSubscriptionSuccess &&\n        context.attemptStartedAt !== undefined\n      ) {\n        const durationMs = Date.now() - context.attemptStartedAt\n        // PostHog implements both trackBillingEvent and\n        // trackMonthlySubscriptionSucceeded (PostHogTelemetryProvider.ts:405,\n        // :444), so calling the legacy event for a plan the server activated\n        // on the spot would double-count that success for it. Only a subscribe\n        // the server charged for reaches the legacy event below, which is the\n        // set billingOperationStore.ts's success handler counts for the\n        // providers that need it (Mixpanel, GTM) on the legacy path.\n        telemetry?.trackBillingEvent({\n          operation: 'subscription_checkout',\n          stage: 'succeeded',\n          outcome: 'success',\n          tier: context.tier,\n          cycle: context.cycle,\n          checkout_type: context.checkoutType,\n          payment_intent_source: paymentIntentSource,\n          billing_op_id: response.billing_op_id,\n          duration_ms: durationMs\n        })\n        if (!response.operationObserved) {\n          telemetry?.trackBillingEvent({\n            operation: 'operation',\n            stage: 'succeeded',\n            outcome: 'success',\n            operation_type: 'subscription',\n            billing_client: billingClientOf(useSubscriptionRail()),\n            tier: context.tier,\n            cycle: context.cycle,\n            checkout_type: context.checkoutType,\n            payment_intent_source: paymentIntentSource,\n            billing_op_id: response.billing_op_id,\n            duration_ms: durationMs\n          })\n        }\n        if (response.requiredPayment) {\n          telemetry?.trackMonthlySubscriptionSucceeded({\n            tier: context.tier,\n            cycle: context.cycle,\n            checkout_type: context.checkoutType,\n            payment_intent_source: paymentIntentSource,\n            billing_op_id: response.billing_op_id\n          })\n        }\n      }\n      // The poller announced every subscription operation it settled, whatever\n      // the caller was tracking; on this rail there is no poller to do it.\n      if (response.requiredPayment) {\n        toast.success(t('billingOperation.subscriptionSuccess'), {\n          duration: 5000\n        })\n      }\n      checkoutStep.value = 'success'\n      return\n    }\n\n    savePendingCheckout(response.billing_op_id, context)\n\n    let initialActionUrl: string | undefined\n    if (response.status === 'needs_payment_method') {\n      if (!response.payment_method_url) {\n        throw new Error(t('subscription.preview.stripeUnavailable'))\n      }\n      initialActionUrl = response.payment_method_url\n      // The open runs after `await subscribe(...)`, so it's not a direct user\n      // gesture and can be popup-blocked; offer a button click as a retry\n      // gesture instead of failing silently.\n      if (!openBillingUrl(initialActionUrl)) {\n        const paymentMethodUrl = initialActionUrl\n        const opId = response.billing_op_id\n        paymentRecoveryToasts.push(\n          toast.warning(t('g.warning'), {\n            description: t('subscription.preview.paymentPopupBlocked'),\n            action: {\n              label: t('subscription.planLoadErrorRetry'),\n              // Not the mutation lock, which is released once the op is adopted.\n              onClick: () => {\n                if (activeCheckoutOperationId.value !== opId) return\n                window.open(paymentMethodUrl, '_blank')\n              }\n            }\n          })\n        )\n      }\n    }\n    await advanceToSuccessOnOperation(\n      response.billing_op_id,\n      context,\n      initialActionUrl,\n      mutationToken\n    )\n  }\n\n  function savePendingCheckout(\n    operationId: string,\n    context: SubscriptionOutcomeContext\n  ): void {\n    const workspaceId = workspaceStore.activeWorkspaceId\n    const ownerUid = useAuthStore().userId\n    if (!workspaceId || !ownerUid) return\n    const attemptedAt = context.attemptStartedAt ?? Date.now()\n\n    if (context.tier === 'team') {\n      const teamCreditStopId = selectedTeamCheckout.value?.stop.id\n      if (!teamCreditStopId) return\n      savePendingSubscriptionCheckout({\n        operationId,\n        workspaceId,\n        ownerUid,\n        selection: {\n          planMode: 'team',\n          teamCreditStopId,\n          billingCycle: context.cycle\n        },\n        attemptedAt\n      })\n      return\n    }\n\n    savePendingSubscriptionCheckout({\n      operationId,\n      workspaceId,\n      ownerUid,\n      selection: {\n        planMode: 'personal',\n        tierKey: context.tier,\n        billingCycle: context.cycle\n      },\n      attemptedAt\n    })\n  }\n\n  // A Stripe-backed subscribe finishes asynchronously: await the billing op and\n  // advance to the success step ourselves. The store refreshes status/balance\n  // before resolving and surfaces any failure via toast.\n  async function advanceToSuccessOnOperation(\n    opId: string,\n    context: SubscriptionOutcomeContext,\n    initialActionUrl: string | undefined,\n    mutationToken: number\n  ) {\n    activeCheckoutOperationId.value = opId\n    const metadata = {\n      tier: context.tier,\n      cycle: context.cycle,\n      checkoutType: context.checkoutType,\n      paymentIntentSource,\n      attemptStartedAt: context.attemptStartedAt,\n      ...(embeddedCheckoutEnabled && {\n        suppressProcessingToast: true,\n        autoHandleRequiresAction: true\n      })\n    }\n    const terminalOperation = initialActionUrl\n      ? billingOperationStore.startOperation(\n          opId,\n          'subscription',\n          metadata,\n          initialActionUrl\n        )\n      : billingOperationStore.startOperation(opId, 'subscription', metadata)\n    // The submit is over once the operation is adopted: isPolling is the busy\n    // state from here, and it is already true because startOperation registers\n    // synchronously above. Holding either of these past this point kept the\n    // recovery prompt's own CTA and Back disabled for a checkout parked on the\n    // customer — and the lock made the CTA a no-op even once it looked live,\n    // because the click re-enters handleSubscription and fails the gate. For\n    // awaiting_payment_method the operation may not go terminal until the\n    // customer performs exactly that action, so waiting for the outer finally\n    // deadlocks the recovery. Releasing neither stops the poll; the outer\n    // finally still runs, and finishCheckoutMutation is idempotent.\n    isSubscribing.value = false\n    finishCheckoutMutation(mutationToken)\n    const operation = await terminalOperation\n    clearPendingSubscriptionCheckoutIfTerminal(opId, operation.status)\n    if (\n      operation.status === 'succeeded' &&\n      activeCheckoutOperationId.value === opId &&\n      operation.workspaceId === workspaceStore.activeWorkspaceId\n    ) {\n      checkoutStep.value = 'success'\n    }\n  }\n\n  async function handleTeamSubscription(\n    confirmReactivation = false,\n    confirmationToken?: string,\n    promotionCode?: string\n  ) {\n    if (\n      isLoadingPreview.value ||\n      isSubscribing.value ||\n      !selectedTeamCheckout.value ||\n      !canPerformCheckout(selectedTeamCheckout.value.checkoutType)\n    ) {\n      return\n    }\n    const mutationToken = beginCheckoutMutation()\n    if (!mutationToken) return\n\n    const teamCheckout = selectedTeamCheckout.value\n    if (!teamCheckout.stop.id) {\n      toast.error(t('subscription.teamPlan.name'), {\n        description: t('subscription.teamPlan.unavailable')\n      })\n      finishCheckoutMutation(mutationToken)\n      return\n    }\n\n    const { stop, checkoutType } = teamCheckout\n    const billingCycle = selectedBillingCycle.value\n    const planSlug = getTeamPlanSlug(billingCycle)\n\n    isSubscribing.value = true\n    try {\n      await fetchStatus()\n      if (!confirmReactivation && requiresReactivationConfirmation()) {\n        const blocked = await refreshPreviewOnReactivationBlock(planSlug, {\n          teamCreditStopId: stop.id\n        })\n        if (blocked) return\n      }\n      const attemptStartedAt = trackSubscriptionStarted({\n        tier: 'team',\n        cycle: billingCycle,\n        checkoutType\n      })\n      if (confirmReactivation && requiresReactivationConfirmation()) {\n        await assertReactivationAmountUnchanged(planSlug, {\n          teamCreditStopId: stop.id\n        })\n      }\n      const quote = embeddedCheckoutEnabled ? previewData.value : null\n      if (embeddedCheckoutEnabled && quote && !quoteIsCurrent.value) {\n        throw new Error(t('subscription.preview.applyQuoteBeforeContinuing'))\n      }\n      const submittingJourney = getActiveCheckoutJourney()\n      if (submittingJourney) {\n        trackCheckoutJourneyPhase(submittingJourney, { phase: 'submitted' })\n      }\n      const response = await subscribe(planSlug, {\n        ...(embeddedCheckoutEnabled &&\n          buildPaymentOptions(quote, confirmationToken, promotionCode)),\n        teamCreditStopId: stop.id,\n        billingCycle,\n        returnUrl: embeddedCheckoutEnabled\n          ? paymentReturnUrl()\n          : `${getComfyPlatformBaseUrl()}/payment/success`,\n        cancelUrl: `${getComfyPlatformBaseUrl()}/payment/failed`,\n        confirmReactivation,\n        prorationAt: previewData.value?.is_immediate\n          ? previewData.value.proration_at\n          : undefined,\n        attemptStartedAt\n      })\n\n      if (response) {\n        linkSubmittingJourneyToOperation(\n          submittingJourney,\n          response.billing_op_id\n        )\n        trackWorkspaceCheckoutStarted({\n          tier: 'team',\n          cycle: billingCycle,\n          checkoutType,\n          billingOpId: response.billing_op_id,\n          paymentIntentSource\n        })\n      }\n      await handleSubscribeResponse(\n        response,\n        {\n          tier: 'team',\n          cycle: billingCycle,\n          checkoutType,\n          attemptStartedAt\n        },\n        true,\n        mutationToken\n      )\n      activeCheckoutAttemptStartedAt = undefined\n    } catch (error) {\n      if (\n        hasErrorCode(error, 'REACTIVATION_CONFIRMATION_REQUIRED') &&\n        (await refreshPreviewOnReactivationBlock(planSlug, {\n          teamCreditStopId: stop.id\n        }))\n      ) {\n        return\n      }\n      trackSubscriptionFailure(\n        {\n          tier: 'team',\n          cycle: billingCycle,\n          checkoutType,\n          attemptStartedAt: activeCheckoutAttemptStartedAt\n        },\n        error\n      )\n      activeCheckoutAttemptStartedAt = undefined\n      if (await recoverOutstandingPayment(error)) return\n      if (\n        await refreshExpiredProrationQuote(error, planSlug, {\n          teamCreditStopId: stop.id\n        })\n      )\n        return\n      if (embeddedCheckoutEnabled && (await recoverStaleQuote(error))) return\n      showSubscribeError(error)\n    } finally {\n      isSubscribing.value = false\n      finishCheckoutMutation(mutationToken)\n    }\n  }\n\n  async function handleResubscribe() {\n    if (!canReactivatePlan.value) return\n\n    if (openHostedBillingTab('subscription', { source: paymentIntentSource })) {\n      emit('close', false)\n      return\n    }\n\n    const source = 'pricing_dialog' as const\n    const startedAt = Date.now()\n    const isWorkspaceResubscribe = shouldUseWorkspaceBilling.value\n\n    telemetry?.trackResubscribeClicked({\n      source,\n      payment_intent_source: paymentIntentSource\n    })\n    // Emitted before the awaited call so a failure always has a preceding\n    // `started` — emitting it only after the call meant a failure produced a\n    // `failed` with no matching `started`, pushing failed/started over 100%.\n    telemetry?.trackBillingEvent({\n      operation: 'resubscribe',\n      stage: 'started',\n      outcome: 'pending',\n      source,\n      payment_intent_source: paymentIntentSource\n    })\n    isResubscribing.value = true\n    try {\n      await resubscribe({ source })\n      // Workspace's resubscribe() call is itself the terminal reactivation, so it\n      // gets an immediate `succeeded` here. Legacy only opens a Stripe checkout\n      // tab, which isn't terminal — its `succeeded` is emitted later, from\n      // useSubscription.ts's pending-checkout recovery, once a status poll\n      // confirms the payment actually went through.\n      if (isWorkspaceResubscribe) {\n        telemetry?.trackBillingEvent({\n          operation: 'resubscribe',\n          stage: 'succeeded',\n          outcome: 'success',\n          source,\n          payment_intent_source: paymentIntentSource,\n          duration_ms: Date.now() - startedAt\n        })\n      }\n      toast.success(t('subscription.resubscribeSuccess'), { duration: 5000 })\n      emit('close', true)\n    } catch (error) {\n      telemetry?.trackBillingEvent({\n        operation: 'resubscribe',\n        stage: 'failed',\n        outcome: 'failure',\n        source,\n        payment_intent_source: paymentIntentSource,\n        failure_category: categorizeBillingApiError(error),\n        ...(isWorkspaceResubscribe && {\n          duration_ms: Date.now() - startedAt\n        })\n      })\n      toast.error(t('g.error'), {\n        description:\n          getErrorMessage(error) ?? t('subscription.resubscribeFailed')\n      })\n    } finally {\n      isResubscribing.value = false\n    }\n  }\n\n  function handleSubscriptionPayment(\n    confirmationToken: string,\n    promotionCode?: string\n  ) {\n    return handleSubscription(false, confirmationToken, promotionCode)\n  }\n\n  function handleTeamSubscriptionPayment(\n    confirmationToken: string,\n    promotionCode?: string\n  ) {\n    return handleTeamSubscription(false, confirmationToken, promotionCode)\n  }\n\n  return {\n    checkoutStep,\n    isLoadingPreview,\n    loadingTier,\n    isSubscribing,\n    isApplyingPromotionCode,\n    isResubscribing,\n    previewData,\n    reactivationRequired,\n    quoteIsCurrent,\n    savedPaymentMethods,\n    selectedSavedPaymentMethodId,\n    selectedTierKey,\n    selectedTeamStop,\n    selectedBillingCycle,\n    activeCheckoutActionUrl,\n    authenticationState,\n    authenticationError,\n    reconciliationOperationId,\n    parkedCheckoutRecovery,\n    isPolling,\n    paymentCancelable,\n    isCancelingPayment,\n    cancelPaymentError,\n    cancelPayment,\n    isTeamCheckout,\n    previewVariant,\n    handleSubscribeClick,\n    handleSubscribeTeamClick,\n    handleBackToPricing,\n    handleSuccessClose,\n    handleAddCreditCard: handleSubscription,\n    handleConfirmTransition: handleSubscription,\n    handleTeamSubscribe: handleTeamSubscription,\n    handleSubscriptionPayment,\n    handleTeamSubscriptionPayment,\n    applyPromotionCode,\n    invalidateQuote,\n    handleResubscribe\n  }\n}\n","import type {\n  CheckoutCopy,\n  CheckoutPlan,\n  CheckoutSuccessCopy\n} from '@comfyorg/account-ui/billing/checkout'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { TeamPlanSelection } from '@/platform/cloud/subscription/constants/teamPlanCreditStops'\nimport {\n  getTierCredits,\n  getTierPrice\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\n\n/**\n * The app's translations and catalog for the shared checkout steps.\n * Sentences that wrap an element around a placeholder keep their `{name}`\n * tokens for the component to split.\n */\nexport function useCheckoutCopy() {\n  const { t } = useI18n()\n\n  const keepTokens = (keys: readonly string[]) =>\n    Object.fromEntries(keys.map((key) => [key, `{${key}}`]))\n  const reactivationTokens = keepTokens([\n    'plan',\n    'date',\n    'newPlan',\n    'nextDate',\n    'amount'\n  ])\n\n  const copy = computed<CheckoutCopy>(() => ({\n    back: t('g.back'),\n    usdPerMonth: t('subscription.usdPerMonth'),\n    billedMonthly: t('subscription.billedMonthly'),\n    billedYearly: (total) => t('subscription.billedYearly', { total }),\n    eachMonthCreditsRefill: t('subscription.preview.eachMonthCreditsRefill'),\n    eachYearCreditsRefill: t('subscription.preview.eachYearCreditsRefill'),\n    totalDueToday: t('subscription.preview.totalDueToday'),\n    renewsAt: (amount, date) =>\n      t('subscription.preview.renewsAt', { amount, date }),\n    renewsAtAmount: (amount) =>\n      t('subscription.preview.renewsAtAmount', { amount }),\n    discount: {\n      plan: t('subscription.preview.discount.plan'),\n      promotion: t('subscription.preview.discount.promotion')\n    },\n    promoCodePlaceholder: t('subscription.preview.promoCodePlaceholder'),\n    applyPromoCode: t('subscription.preview.applyPromoCode'),\n    reconciliationTitle: t('billingOperation.reconciliationTitle'),\n    reconciliationDetail: t('billingOperation.reconciliationDetail'),\n    authenticationFailedDetail: t(\n      'billingOperation.authenticationFailedDetail'\n    ),\n    pendingVerificationDetail: t(\n      'subscription.preview.pendingVerificationDetail'\n    ),\n    completeVerification: t('subscription.preview.completeVerification'),\n    cancelPaymentAndRetry: t('subscription.preview.cancelPaymentAndRetry'),\n    confirmPayment: t('subscription.preview.confirmPayment'),\n    startingToday: t('subscription.preview.startingToday'),\n    parkedCheckoutDetail: t('subscription.preview.parkedCheckoutDetail'),\n    completePayment: t('subscription.preview.completePayment'),\n    payAndSubscribe: t('subscription.preview.payAndSubscribe'),\n    subscribeToPlan: (plan) =>\n      t('subscription.preview.subscribeToPlan', { plan }),\n    confirmUpgradeTitle: t('subscription.preview.confirmUpgradeTitle'),\n    confirmChangeTitle: t('subscription.preview.confirmChangeTitle'),\n    switchesToday: t('subscription.preview.switchesToday'),\n    startsOn: (date) => t('subscription.preview.startsOn', { date }),\n    creditsYoullGetToday: t('subscription.preview.creditsYoullGetToday'),\n    refillReplacesNote: t('subscription.preview.refillReplacesNote'),\n    afterThat: t('subscription.preview.afterThat'),\n    creditsRefillMonthlyTo: t('subscription.preview.creditsRefillMonthlyTo'),\n    billedEachMonth: (amount) =>\n      t('subscription.preview.billedEachMonth', { amount }),\n    discountComposition: t('subscription.preview.discountComposition'),\n    quoteUnavailable: t('subscription.preview.quoteUnavailable'),\n    confirmUpgradeCta: t('subscription.preview.confirmUpgradeCta'),\n    confirmChange: t('subscription.preview.confirmChange'),\n    reactivation: {\n      title: t('subscription.preview.reactivation.title'),\n      titleAnnual: t('subscription.preview.reactivation.titleAnnual'),\n      upgradeBody: t(\n        'subscription.preview.reactivation.upgradeBody',\n        reactivationTokens\n      ),\n      downgradeBody: t(\n        'subscription.preview.reactivation.downgradeBody',\n        reactivationTokens\n      ),\n      durationChangeBody: t(\n        'subscription.preview.reactivation.durationChangeBody',\n        reactivationTokens\n      ),\n      durationChangeBodyMonthly: t(\n        'subscription.preview.reactivation.durationChangeBodyMonthly',\n        reactivationTokens\n      ),\n      withoutRenewalDate: {\n        upgradeBody: t(\n          'subscription.preview.reactivation.withoutRenewalDate.upgradeBody',\n          reactivationTokens\n        ),\n        downgradeBody: t(\n          'subscription.preview.reactivation.withoutRenewalDate.downgradeBody',\n          reactivationTokens\n        ),\n        durationChangeBody: t(\n          'subscription.preview.reactivation.withoutRenewalDate.durationChangeBody',\n          reactivationTokens\n        ),\n        durationChangeBodyMonthly: t(\n          'subscription.preview.reactivation.withoutRenewalDate.durationChangeBodyMonthly',\n          reactivationTokens\n        )\n      },\n      confirmButton: t('subscription.preview.reactivation.confirmButton'),\n      confirmButtonWithCharge: (amount) =>\n        t('subscription.preview.reactivation.confirmButtonWithCharge', {\n          amount\n        }),\n      checkboxLabel: (amount) =>\n        t('subscription.preview.reactivation.checkboxLabel', { amount })\n    },\n    savedMethod: {\n      savedPaymentMethod: t('subscription.preview.savedPaymentMethod'),\n      changePaymentMethod: t('subscription.preview.changePaymentMethod'),\n      addNewPaymentMethod: t('subscription.preview.addNewPaymentMethod'),\n      alipay: t('subscription.preview.alipay'),\n      selectLabel: t('g.singleSelectDropdown')\n    },\n    terms: {\n      agreement: t(\n        'subscription.preview.termsAgreement',\n        keepTokens(['terms', 'privacy'])\n      ),\n      terms: t('subscription.preview.terms'),\n      privacyPolicy: t('subscription.preview.privacyPolicy')\n    },\n    payment: {\n      paymentMethod: t('subscription.preview.paymentMethod'),\n      methodChoice: t('subscription.preview.stripeMethodChoice'),\n      billingAddress: t('subscription.preview.billingAddress'),\n      alipayRenewalNote: t('subscription.preview.alipayRenewalNote'),\n      unavailable: t('subscription.preview.stripeUnavailable'),\n      genericError: t('g.error')\n    }\n  }))\n\n  const successCopy = computed<CheckoutSuccessCopy>(() => ({\n    allSet: t('subscription.success.allSet'),\n    planUpdated: t('subscription.success.planUpdated'),\n    receiptEmailed: t('subscription.success.receiptEmailed'),\n    usdPerMonth: t('subscription.usdPerMonth'),\n    usdPerYear: t('subscription.usdPerYear'),\n    perMonth: t('subscription.perMonth'),\n    perYear: t('subscription.perYear'),\n    promoApplied: (code) => t('subscription.success.promoApplied', { code }),\n    promoRenews: (amount, date) =>\n      t('subscription.success.promoRenews', { amount, date }),\n    close: t('g.close')\n  }))\n\n  function checkoutPlan(\n    tierKey: Exclude<TierKey, 'free' | 'founder'> | null | undefined,\n    teamPlan: TeamPlanSelection | null\n  ): CheckoutPlan {\n    if (teamPlan) {\n      return {\n        name: t('subscription.teamPlan.name'),\n        monthlyPriceUsd: {\n          monthly: teamPlan.discountedUsd,\n          yearly: teamPlan.discountedUsd\n        },\n        monthlyCredits: teamPlan.credits,\n        pricedByQuote: false\n      }\n    }\n    return {\n      name: t(`subscription.tiers.${tierKey}.name`),\n      monthlyPriceUsd: {\n        monthly: tierKey ? getTierPrice(tierKey, false) : 0,\n        yearly: tierKey ? getTierPrice(tierKey, true) : 0\n      },\n      monthlyCredits: tierKey ? (getTierCredits(tierKey) ?? 0) : 0,\n      pricedByQuote: true\n    }\n  }\n\n  return { copy, successCopy, checkoutPlan }\n}\n","<template>\n  <CheckoutSubscribeConfirm\n    v-model:selected-saved-method-id=\"selectedSavedMethodId\"\n    :plan\n    :copy\n    :locale\n    :publishable-key\n    :theme-key=\"colorPaletteStore.activePaletteId\"\n    :billing-cycle\n    :is-loading\n    :preview-data\n    :action-url\n    :authentication-state\n    :authentication-error\n    :reconciliation-operation-id\n    :parked-checkout-recovery\n    :use-payment-element\n    :saved-methods\n    :quote-is-current\n    :is-applying-promotion-code\n    :embedded-checkout-enabled\n    @add-credit-card=\"emit('addCreditCard')\"\n    @confirm-payment=\"emit('confirmPayment', $event)\"\n    @back=\"emit('back')\"\n    @change-payment-method=\"emit('changePaymentMethod')\"\n    @apply-promotion-code=\"emit('applyPromotionCode', $event)\"\n    @invalidate-quote=\"emit('invalidateQuote')\"\n    @payment-phase=\"emitPaymentJourneyPhase\"\n  />\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The cloud app's binding of the shared new-subscription confirm: its tier\n * and team-stop catalog, its translations, its Stripe key and theme, and its\n * checkout-journey telemetry (ADR BILLING-WEB-0038).\n */\nimport { CheckoutSubscribeConfirm } from '@comfyorg/account-ui/billing/checkout'\nimport type { StripePaymentPhase } from '@comfyorg/account-ui/billing/stripe'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { TeamPlanSelection } from '@/platform/cloud/subscription/constants/teamPlanCreditStops'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport type {\n  BillingAuthenticationState,\n  PreviewSubscribeResponse,\n  SavedPaymentMethod\n} from '@/platform/workspace/api/workspaceApi'\nimport { resolveStripePublishableKey } from '@/platform/workspace/billing/stripePublishableKey'\nimport { useCheckoutCopy } from '@/platform/workspace/composables/useCheckoutCopy'\nimport { getActiveCheckoutJourney } from '@/platform/workspace/utils/checkoutJourney'\nimport { trackCheckoutJourneyPhase } from '@/platform/workspace/utils/checkoutJourneyTelemetry'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\n\ninterface Props {\n  /** Personal-tier checkout. Required unless `teamPlan` is set. */\n  tierKey?: Exclude<TierKey, 'free' | 'founder'>\n  billingCycle?: BillingCycle\n  isLoading?: boolean\n  previewData?: PreviewSubscribeResponse | null\n  /** Team-plan checkout (selected slider stop); overrides tier-derived display. */\n  teamPlan?: TeamPlanSelection | null\n  actionUrl?: string | null\n  authenticationState?: BillingAuthenticationState | null\n  authenticationError?: string | null\n  reconciliationOperationId?: string | null\n  parkedCheckoutRecovery?: boolean\n  usePaymentElement?: boolean\n  savedMethods?: SavedPaymentMethod[] | null\n  quoteIsCurrent?: boolean\n  isApplyingPromotionCode?: boolean\n  embeddedCheckoutEnabled?: boolean\n}\n\nconst {\n  tierKey,\n  billingCycle = 'monthly',\n  isLoading = false,\n  previewData = null,\n  teamPlan = null,\n  actionUrl = null,\n  authenticationState = null,\n  authenticationError = null,\n  reconciliationOperationId = null,\n  parkedCheckoutRecovery = false,\n  usePaymentElement = false,\n  savedMethods = null,\n  quoteIsCurrent = false,\n  isApplyingPromotionCode = false,\n  embeddedCheckoutEnabled = false\n} = defineProps<Props>()\n\nconst emit = defineEmits<{\n  addCreditCard: []\n  confirmPayment: [confirmationToken: string]\n  back: []\n  changePaymentMethod: []\n  applyPromotionCode: [code: string]\n  invalidateQuote: []\n}>()\n\nconst selectedSavedMethodId = defineModel<string | null>(\n  'selectedSavedMethodId',\n  { default: null }\n)\n\nconst { locale } = useI18n()\nconst { copy, checkoutPlan } = useCheckoutCopy()\nconst colorPaletteStore = useColorPaletteStore()\n\nconst publishableKey = resolveStripePublishableKey() ?? ''\n\nconst plan = computed(() => checkoutPlan(tierKey, teamPlan))\n\nfunction emitPaymentJourneyPhase(phase: StripePaymentPhase): void {\n  // The form stops reporting once unmounted; what it cannot know is whether\n  // the active journey is still the one this checkout started.\n  const journey = getActiveCheckoutJourney()\n  if (!journey) return\n  trackCheckoutJourneyPhase(journey, phase)\n}\n</script>\n","<template>\n  <CheckoutSuccess\n    :plan=\"checkoutPlan(tierKey, teamPlan)\"\n    :copy=\"successCopy\"\n    :locale\n    :preview-data\n    :billing-cycle\n    :dark-surface\n    :promo-applied\n    :close-demoted=\"showInviteBlock && invitedEmails.length === 0\"\n    @close=\"$emit('close')\"\n  >\n    <template #details>\n      <div v-if=\"showInviteBlock\" class=\"mt-4 flex w-full flex-col gap-2\">\n        <h3 class=\"m-0 text-base font-normal text-base-foreground\">\n          {{ $t('subscription.success.inviteTitle') }}\n        </h3>\n        <p class=\"m-0 text-sm text-muted-foreground\">\n          {{ $t('subscription.success.inviteSubtext') }}\n        </p>\n        <div aria-live=\"polite\">\n          <p\n            v-if=\"invitedEmails.length > 0\"\n            ref=\"invitedMessage\"\n            tabindex=\"-1\"\n            class=\"m-0 text-sm text-success-background\"\n          >\n            {{\n              $t(\n                'workspacePanel.inviteMemberDialog.invitedMessage',\n                { emails: invitedEmails.join(', ') },\n                invitedEmails.length\n              )\n            }}\n          </p>\n          <InviteMembersForm\n            v-else\n            ref=\"inviteForm\"\n            :show-submit=\"false\"\n            :tags-input-class=\"\n              darkSurface\n                ? 'min-h-10 w-full bg-secondary-background px-3 focus-within:bg-secondary-background hover:bg-secondary-background-hover'\n                : undefined\n            \"\n            source=\"post_upgrade_success\"\n            :submit-label=\"$t('subscription.success.sendInvites')\"\n            :placeholder=\"$t('subscription.success.inviteEmailsPlaceholder')\"\n            :max-seats=\"inviteFormMaxSeats\"\n            :occupied-seats=\"inviteFormOccupiedSeats\"\n            @submitted=\"onInvited\"\n          />\n        </div>\n      </div>\n    </template>\n    <template #actions>\n      <Button\n        v-if=\"showInviteBlock && invitedEmails.length === 0\"\n        variant=\"tertiary\"\n        size=\"lg\"\n        class=\"w-full rounded-lg\"\n        :disabled=\"!canSendInvites\"\n        :loading=\"isSendingInvites\"\n        @click=\"handleSendInvites\"\n      >\n        {{ $t('subscription.success.sendInvites') }}\n      </Button>\n    </template>\n  </CheckoutSuccess>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The cloud app's binding of the shared success step, plus the team invite\n * that follows a multi-seat upgrade (ADR BILLING-WEB-0038).\n */\nimport { CheckoutSuccess } from '@comfyorg/account-ui/billing/checkout'\nimport { computed, nextTick, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport type { TeamPlanSelection } from '@/platform/cloud/subscription/constants/teamPlanCreditStops'\nimport type { TierKey } from '@/platform/cloud/subscription/constants/tierPricing'\nimport type { BillingCycle } from '@/platform/cloud/subscription/utils/subscriptionTierRank'\nimport type { PreviewSubscribeResponse } from '@/platform/workspace/api/workspaceApi'\nimport { useCheckoutCopy } from '@/platform/workspace/composables/useCheckoutCopy'\n\nimport InviteMembersForm from './InviteMembersForm.vue'\n\nconst {\n  tierKey,\n  previewData = null,\n  teamPlan = null,\n  billingCycle = 'monthly',\n  darkSurface = false,\n  promoApplied = null\n} = defineProps<{\n  tierKey?: Exclude<TierKey, 'free' | 'founder'> | null\n  previewData?: PreviewSubscribeResponse | null\n  teamPlan?: TeamPlanSelection | null\n  billingCycle?: BillingCycle\n  /** Dialog paints base-background; the plan card elevates to stay visible. */\n  darkSurface?: boolean\n  /** Applied promotion feedback (Figma 5379-30077 S3). Display-ready strings;\n   *  the backend does not supply this yet — see the promo validation ask. */\n  promoApplied?: {\n    code: string\n    renewalAmount: string\n    renewalDate: string\n  } | null\n}>()\n\ndefineEmits<{\n  close: []\n}>()\n\nconst { locale } = useI18n()\nconst { successCopy, checkoutPlan } = useCheckoutCopy()\nconst { maxSeats, occupiedSeats } = useBillingContext()\n\nconst inviteFormMaxSeats = computed(() => maxSeats.value)\nconst inviteFormOccupiedSeats = computed(() => occupiedSeats.value)\nconst showInviteBlock = computed(\n  () => maxSeats.value === 0 || (maxSeats.value ?? 0) > 1\n)\n\nconst invitedEmails = ref<string[]>([])\nconst invitedMessage = ref<HTMLElement>()\n\nconst inviteForm = ref<InstanceType<typeof InviteMembersForm>>()\nconst canSendInvites = computed(\n  () =>\n    maxSeats.value !== null &&\n    occupiedSeats.value !== null &&\n    (inviteForm.value?.canSubmit ?? false)\n)\nconst isSendingInvites = computed(() => inviteForm.value?.loading ?? false)\n\nfunction handleSendInvites() {\n  if (maxSeats.value === null || occupiedSeats.value === null) return\n  void inviteForm.value?.submit()?.catch(console.error)\n}\n\nasync function onInvited(emails: string[]) {\n  invitedEmails.value = emails\n  await nextTick()\n  invitedMessage.value?.focus()\n}\n</script>\n","<template>\n  <CheckoutTransitionConfirm\n    :preview-data\n    :plan\n    :current-plan-name=\"currentTierName\"\n    :copy\n    :locale\n    :subscription-loaded=\"subscription !== null\"\n    :subscription-cancelled=\"subscription?.isCancelled ?? false\"\n    :subscription-end-date=\"subscription?.endDate\"\n    :is-loading\n    :action-url\n    :force-reactivation\n    :authentication-state\n    :authentication-error\n    :reconciliation-operation-id\n    :quote-is-current\n    :is-applying-promotion-code\n    :embedded-checkout-enabled\n    :payment-cancelable\n    :canceling-payment\n    :cancel-payment-error\n    @cancel-payment=\"emit('cancelPayment')\"\n    @confirm=\"emit('confirm', $event)\"\n    @back=\"emit('back')\"\n    @apply-promotion-code=\"emit('applyPromotionCode', $event)\"\n    @invalidate-quote=\"emit('invalidateQuote')\"\n  />\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The cloud app's binding of the shared plan-change confirm: its tier names\n * and credits, its translations, and the subscription status that decides\n * whether the change reactivates a cancelled plan (ADR BILLING-WEB-0038).\n */\nimport { CheckoutTransitionConfirm } from '@comfyorg/account-ui/billing/checkout'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport type { TeamPlanSelection } from '@/platform/cloud/subscription/constants/teamPlanCreditStops'\nimport type { IngestSubscriptionTier } from '@/platform/cloud/subscription/constants/tierPricing'\nimport {\n  getTierCredits,\n  toTierKey\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport type {\n  BillingAuthenticationState,\n  PreviewSubscribeResponse\n} from '@/platform/workspace/api/workspaceApi'\nimport { useCheckoutCopy } from '@/platform/workspace/composables/useCheckoutCopy'\n\nconst {\n  previewData,\n  isLoading = false,\n  teamPlan = null,\n  actionUrl = null,\n  forceReactivation = false,\n  authenticationState = null,\n  authenticationError = null,\n  reconciliationOperationId = null,\n  quoteIsCurrent = false,\n  isApplyingPromotionCode = false,\n  embeddedCheckoutEnabled = false,\n  paymentCancelable = false,\n  cancelingPayment = false,\n  cancelPaymentError = null\n} = defineProps<{\n  previewData: PreviewSubscribeResponse\n  isLoading?: boolean\n  /** Set for a team credit-commit change: plan name + refill credits come from\n   *  the selected slider stop; all proration money stays driven by previewData. */\n  teamPlan?: TeamPlanSelection | null\n  actionUrl?: string | null\n  /** Server-authoritative fallback for legacy status reads that omit a\n   * scheduled cancellation until subscribe enforces the consent gate. */\n  forceReactivation?: boolean\n  authenticationState?: BillingAuthenticationState | null\n  authenticationError?: string | null\n  reconciliationOperationId?: string | null\n  quoteIsCurrent?: boolean\n  isApplyingPromotionCode?: boolean\n  embeddedCheckoutEnabled?: boolean\n  paymentCancelable?: boolean\n  cancelingPayment?: boolean\n  cancelPaymentError?: string | null\n}>()\n\nconst emit = defineEmits<{\n  confirm: [confirmReactivation: boolean]\n  back: []\n  applyPromotionCode: [code: string]\n  invalidateQuote: []\n  cancelPayment: []\n}>()\n\nconst { locale, t, te } = useI18n()\nconst { copy } = useCheckoutCopy()\nconst { subscription } = useBillingContext()\n\nfunction formatTierName(tier: string): string {\n  const nameKey = `subscription.tiers.${tier.toLowerCase()}.name`\n  if (te(nameKey)) return t(nameKey)\n  return tier\n    .toLowerCase()\n    .split(/[_-]+/)\n    .filter(Boolean)\n    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))\n    .join(' ')\n}\n\n// Lowercasing the tier is not a catalog lookup: FOUNDERS_EDITION keys as\n// 'founder', and TEAM/ENTERPRISE/unrecognized tiers key as nothing at all.\nfunction tierMonthlyCredits(tier: string): number {\n  const tierKey = toTierKey(tier as IngestSubscriptionTier)\n  return tierKey ? (getTierCredits(tierKey) ?? 0) : 0\n}\n\nconst plan = computed(() =>\n  teamPlan\n    ? {\n        name: t('subscription.teamPlan.name'),\n        monthlyCredits: teamPlan.credits\n      }\n    : {\n        name: formatTierName(previewData.new_plan.tier),\n        monthlyCredits: tierMonthlyCredits(previewData.new_plan.tier)\n      }\n)\n\nconst currentTierName = computed(() => {\n  const tier = previewData.current_plan?.tier\n  if (!tier) return ''\n  return tier.toUpperCase() === 'TEAM'\n    ? t('subscription.teamPlan.name')\n    : formatTierName(tier)\n})\n</script>\n"],"file":"SubscriptionTransitionPreviewWorkspace-A9yK2UH9.js"}"""

